#!/usr/bin/env bash
# Ollama + Cloudflare Tunnel quick/named setup for Debian/Ubuntu containers.
# Requires root for setup/restart/stop. Quick Tunnel URLs are temporary and
# publicly reachable. This script intentionally does NOT configure Cloudflare
# Access: anyone who can reach the tunnel URL/hostname can use the Ollama API.
# Distribution note: the published ollama-cloudflare-setup.sh is generated by
# build.sh from src/*.sh and tui/ola_tui.py; edit those sources, not the
# generated artifact.
set -Eeuo pipefail

SUP_DIR="/etc/supervisor/conf.d"
SUP_CONF="/etc/supervisor/supervisord.conf"
LOG_DIR="/var/log/supervisor"
CF_CONF_DIR="/etc/cloudflared"
CF_CLI_HOME="${HOME:-/root}/.cloudflared"
URL_FILE="/etc/ollama-cloudflare-url"
MODEL_FILE="/etc/ollama-cloudflare-model"
SPEED_FILE="/etc/ollama-cloudflare-speed"
KEEPALIVE_FILE="/etc/ollama-cloudflare-keepalive"
FLUID_WARM_KEEP_ALIVE="30m"
MODEL_DEFAULT="qwen3:1.7b"
OLLAMA_USER="ollama"
CLOUDFLARED_USER="cloudflared"
OLLAMA_GROUP=""
CLOUDFLARED_GROUP=""
OLLAMA_HOME=""
OLLAMA_CONTEXT_LENGTH="${OLLAMA_CONTEXT_LENGTH:-1024}"
CF_TUNNEL_PROTOCOL="${CF_TUNNEL_PROTOCOL:-auto}"
OLA_BIN_DIR="/usr/local/bin"
OLA_COMMAND="$OLA_BIN_DIR/ola"
OLA_INSTALL_DIR="/usr/local/lib/ollama-cloudflare"
OLA_SCRIPT="$OLA_INSTALL_DIR/ollama-cloudflare-setup.sh"
OLA_TUI_FILE="$OLA_INSTALL_DIR/ola_tui.py"
OLA_TUI_VENV="$OLA_INSTALL_DIR/tui-venv"
OLA_TUI_PYTHON="$OLA_TUI_VENV/bin/python"
OLA_TUI_REQUIREMENTS="$OLA_INSTALL_DIR/tui-requirements.txt"
OLA_TUI_TEXTUAL_VERSION="8.2.8"
WATCHDOG_INTERVAL="${OLA_WATCHDOG_INTERVAL:-60}"
WATCHDOG_FAILURES="${OLA_WATCHDOG_FAILURES:-3}"
WATCHDOG_COOLDOWN="${OLA_WATCHDOG_COOLDOWN:-180}"

info(){ printf '\033[1;34m[INFO]\033[0m %s\n' "$*"; }
ok(){ printf '\033[1;32m[OK]\033[0m %s\n' "$*"; }
warn(){ printf '\033[1;33m[WARN]\033[0m %s\n' "$*"; }
err(){ printf '\033[1;31m[ERROR]\033[0m %s\n' "$*" >&2; }
die(){ err "$*"; exit 1; }

usage(){
  echo "Usage: bash $0 [setup|start|recover|status|doctor|test|bench|speed|fluid|tui|models|use|ps|unload|delete|logs|restart|stop|watchdog]"
  echo "No argument opens an interactive menu."
  echo "setup, start, recover, use, unload, delete, restart, stop, 'speed apply|reset', 'fluid keepalive' and 'tui install' require root; status, doctor, test, speed, fluid status/preset, tui status, models, ps, logs and watchdog are read-only. Bench does not change config or disk files, but may load/unload models in RAM while testing."
  echo "ola tui opens the optional full-screen Textual interface (dashboard and model actions). 'ola tui install' repairs its isolated Python environment; 'ola tui status' reports it."
  echo "After setup, the short system command is available: ola status | ola doctor | ola test | ola recover | ola use <model> | ola delete <model> | ola start | ola logs"
  echo "ola use first unloads any different model currently in RAM, then installs/loads the requested model."
  echo "ola delete (alias: ola rm) unloads the model from RAM first, then permanently deletes it from disk."
  echo "ola bench (or ola bench all) measures every downloaded model one by one; ola bench <model> measures only that model. 'ola bench --stream [model|all]' measures the time to the first visible token and the stream regularity, locally and through the saved public URL when one exists."
  echo "ola fluid shows the fluidity state; 'ola fluid warm [model]' keeps one model warm for 30 minutes; 'ola fluid preset [model]' prints a stable low-latency request preset; 'ola fluid keepalive <duration|reset>' changes the server-wide OLLAMA_KEEP_ALIVE default (5m by default), with automatic rollback."
  echo "ola speed shows CPU/RAM tuning for the whole Ollama server, 'ola speed apply' enables the safe Pack Speed (Flash Attention + q8_0 KV cache) for all models and verifies each present model, 'ola speed reset' restores the defaults. Parallel requests and context size are never raised by Pack Speed."
  echo "In an interactive terminal, ola models opens a model manager: u=use, d=delete, l=unload from RAM, a=add+use, q=quit."
  echo "Environment: CF_TUNNEL_PROTOCOL=auto|http2|quic (default auto), OLLAMA_TMPDIR=<large temp dir>."
}

script_source_path(){
  local src=${BASH_SOURCE[0]:-} dir next
  [[ -n "$src" ]] || return 1
  if [[ "$src" != */* ]]; then
    src=$(command -v -- "$src" 2>/dev/null || true)
    [[ -n "$src" ]] || return 1
  fi
  while [[ -L "$src" ]]; do
    dir=$(cd -P "$(dirname "$src")" 2>/dev/null && pwd) || return 1
    next=$(readlink "$src" 2>/dev/null || true)
    [[ -n "$next" ]] || return 1
    if [[ "$next" == /* ]]; then
      src="$next"
    else
      src="$dir/$next"
    fi
  done
  case "$src" in
    /dev/*|/proc/*) return 1 ;;
  esac
  [[ -f "$src" ]] || return 1
  dir=$(cd -P "$(dirname "$src")" 2>/dev/null && pwd) || return 1
  printf '%s/%s' "$dir" "$(basename "$src")"
}

install_ola_command(){
  local source tmp_script existing_target
  source=$(script_source_path) \
    || die "Could not locate this script as a regular file, so the 'ola' command was not installed. Download the script to a file (for example /tmp/ollama-cloudflare-setup.sh), then run that file."
  install -d -m 0755 "$OLA_BIN_DIR" "$OLA_INSTALL_DIR" \
    || die "Could not create $OLA_INSTALL_DIR or $OLA_BIN_DIR for the 'ola' command."

  if [[ "$source" != "$OLA_SCRIPT" ]]; then
    tmp_script=$(mktemp "$OLA_INSTALL_DIR/.ollama-cloudflare-setup.sh-XXXXXX") \
      || die "Could not create a temporary file in $OLA_INSTALL_DIR for the 'ola' command."
    if ! install -m 0755 "$source" "$tmp_script"; then
      rm -f "$tmp_script"
      die "Could not install this script as $OLA_SCRIPT."
    fi
    mv -f "$tmp_script" "$OLA_SCRIPT" \
      || die "Could not install this script as $OLA_SCRIPT."
  fi
  chmod 0755 "$OLA_SCRIPT" || die "Could not make $OLA_SCRIPT executable."

  if [[ -L "$OLA_COMMAND" ]]; then
    existing_target=$(readlink -f "$OLA_COMMAND" 2>/dev/null || true)
    [[ "$existing_target" == "$OLA_SCRIPT" ]] \
      || die "$OLA_COMMAND already exists and points to '${existing_target:-unknown}', not to this tool. Refusing to overwrite it; rename/remove that command, then re-run."
  elif [[ -e "$OLA_COMMAND" ]]; then
    cmp -s "$OLA_COMMAND" "$OLA_SCRIPT" \
      || die "$OLA_COMMAND already exists and is not this tool. Refusing to overwrite it; rename/remove that file, then re-run."
  fi
  ln -sfn "$OLA_SCRIPT" "$OLA_COMMAND" \
    || die "Could not create the short command $OLA_COMMAND."
  install_ola_tui_files \
    || die "Could not install the TUI application file in $OLA_INSTALL_DIR."
  hash -r 2>/dev/null || true
  case ":$PATH:" in
    *":$OLA_BIN_DIR:"*) ;;
    *) warn "$OLA_BIN_DIR is not in the current PATH. Use $OLA_COMMAND in this shell, or open a new root shell before typing: ola" ;;
  esac
  ok "Short command installed: ola (examples: ola, ola status, ola start, ola logs)"
}

require_root(){
  [[ $EUID -eq 0 ]] || die "Run as root: sudo bash $0"
}

check_system(){
  [[ -f /etc/os-release ]] || die "Cannot identify Linux distribution."
  # /etc/os-release is a trusted runtime file provided by the OS.
  # shellcheck disable=SC1091
  . /etc/os-release
  [[ "${ID:-}" == debian || "${ID:-}" == ubuntu || "${ID_LIKE:-}" == *debian* ]] || warn "This script is designed for Debian/Ubuntu; continuing anyway."
  command -v apt-get >/dev/null || die "apt-get is required."
}

# Reads one line and prints it (or the default when the user just presses
# Enter). Returns non-zero on EOF so callers can abort instead of silently
# treating "no input" as a default choice.
prompt_value(){
  local prompt=$1 default=${2-} value
  if ! read -r -p "$prompt" value; then
    return 1
  fi
  printf '%s' "${value:-$default}"
}

is_valid_hostname(){
  local h=$1
  [[ ${#h} -le 253 ]] || return 1
  [[ "$h" =~ ^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$ ]] || return 1
  return 0
}

apt_update(){
  apt-get -o DPkg::Lock::Timeout=120 update
}

apt_install(){
  DEBIAN_FRONTEND=noninteractive apt-get -o DPkg::Lock::Timeout=120 install -y "$@"
}

free_kb(){
  local path=$1 kb
  kb=$(df -Pk "$path" 2>/dev/null | awk 'NR == 2 { print $4 }')
  [[ "$kb" =~ ^[0-9]+$ ]] || kb=0
  printf '%s' "$kb"
}

require_commands(){
  local cmd missing=0
  for cmd in "$@"; do
    if ! command -v "$cmd" >/dev/null 2>&1; then
      err "Required command not found: $cmd"
      missing=1
    fi
  done
  [[ "$missing" -eq 0 ]] || die "Missing required commands. Install the base packages first (see setup output above)."
}

nologin_shell(){
  local candidate
  for candidate in /usr/sbin/nologin /sbin/nologin /usr/bin/false /bin/false; do
    if [[ -x "$candidate" ]]; then
      printf '%s' "$candidate"
      return 0
    fi
  done
  printf '%s' "/bin/false"
}

# Verifies an HTTPS URL even when the container resolver cannot resolve the
# public hostname: falls back to Cloudflare DNS-over-HTTPS plus --resolve.
https_url_ready(){
  local url=$1 host json ips ip
  if curl -fsS --max-time 10 "$url" >/dev/null 2>&1; then
    return 0
  fi
  command -v jq >/dev/null 2>&1 || return 1
  host=${url#*://}
  host=${host%%/*}
  [[ -n "$host" && "$host" != "$url" ]] || return 1
  json=$(curl -fsS --max-time 10 "https://1.1.1.1/dns-query?name=${host}&type=A" -H 'accept: application/dns-json' 2>/dev/null) || return 1
  ips=$(printf '%s' "$json" | jq -r '.Answer[]? | select(.type == 1) | .data' 2>/dev/null || true)
  for ip in $ips; do
    [[ "$ip" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || continue
    if curl -fsS --max-time 10 --resolve "${host}:443:${ip}" "$url" >/dev/null 2>&1; then
      return 0
    fi
  done
  return 1
}

ollama_pids(){
  local proc comm
  for proc in /proc/[0-9]*; do
    [[ -r "$proc/comm" ]] || continue
    comm=$(<"$proc/comm")
    if [[ "$comm" == "ollama" ]]; then
      printf '%s\n' "${proc#/proc/}"
    fi
  done
}

any_ollama_process(){
  [[ -n "$(ollama_pids)" ]]
}

select_supervisor_paths(){
  if [[ -f /etc/supervisor/supervisord.conf ]]; then
    SUP_CONF="/etc/supervisor/supervisord.conf"
    SUP_DIR="/etc/supervisor/conf.d"
  elif [[ -f /etc/supervisord.conf ]]; then
    SUP_CONF="/etc/supervisord.conf"
    if [[ -d /etc/supervisord.d ]]; then
      SUP_DIR="/etc/supervisord.d"
    elif [[ -d /etc/supervisor/conf.d ]]; then
      SUP_DIR="/etc/supervisor/conf.d"
    fi
  fi
}

supervisor_ctl(){
  supervisorctl -c "$SUP_CONF" "$@"
}

supervisor_program_running(){
  local program=$1
  command -v supervisorctl >/dev/null 2>&1 || return 1
  [[ -f "$SUP_CONF" ]] || return 1
  supervisor_ctl status "$program" 2>/dev/null | awk '$2 == "RUNNING" { found=1 } END { exit !found }'
}

supervisor_is_running(){
  command -v supervisorctl >/dev/null 2>&1 || return 1
  [[ -f "$SUP_CONF" ]] || return 1
  supervisor_ctl status >/dev/null 2>&1
}

tighten_log_permissions(){
  [[ -d "$LOG_DIR" ]] || return 0
  find "$LOG_DIR" -type f -name '*.log' -exec chmod 600 {} + 2>/dev/null || true
}

ensure_supervisor_running(){
  select_supervisor_paths
  install -d -m 0750 "$SUP_DIR" "$LOG_DIR"
  if ! command -v supervisord >/dev/null || ! command -v supervisorctl >/dev/null; then
    apt_update
    apt_install supervisor
  fi
  [[ -f "$SUP_CONF" ]] || die "Supervisor config not found: $SUP_CONF"
  if ! supervisor_is_running; then
    supervisord -c "$SUP_CONF" >/dev/null 2>&1 || true
    local i
    for i in $(seq 1 10); do
      supervisor_is_running && break
      sleep 1
    done
  fi
  supervisor_is_running || die "Supervisor is not responding. Check $SUP_CONF and any existing supervisor process."
  tighten_log_permissions
}

require_supervisor_running(){
  select_supervisor_paths
  command -v supervisorctl >/dev/null 2>&1 || die "Supervisor is not installed. Run setup first: sudo bash $0 setup"
  [[ -f "$SUP_CONF" ]] || die "Supervisor config not found: $SUP_CONF. Run setup first."
  if ! supervisor_is_running; then
    command -v supervisord >/dev/null 2>&1 || die "supervisord is not installed. Run setup first."
    supervisord -c "$SUP_CONF" >/dev/null 2>&1 || true
    local i
    for i in $(seq 1 10); do
      supervisor_is_running && break
      sleep 1
    done
  fi
  supervisor_is_running || die "Supervisor is not responding. Check $SUP_CONF and any existing supervisor process."
}

supervisor_apply(){
  supervisor_ctl reread || die "Supervisor failed to reread program configs."
  supervisor_ctl update || die "Supervisor failed to apply program configs."
  sleep 2
  tighten_log_permissions
}

ensure_service_users(){
  local shell_path
  shell_path=$(nologin_shell)
  if ! id -u "$OLLAMA_USER" >/dev/null 2>&1; then
    useradd --system --create-home --home-dir /var/lib/ollama --shell "$shell_path" "$OLLAMA_USER" \
      || die "Could not create the dedicated '$OLLAMA_USER' system user."
  fi
  if ! id -u "$CLOUDFLARED_USER" >/dev/null 2>&1; then
    useradd --system --no-create-home --home-dir /nonexistent --shell "$shell_path" "$CLOUDFLARED_USER" \
      || die "Could not create the dedicated '$CLOUDFLARED_USER' system user."
  fi
  OLLAMA_GROUP=$(id -gn "$OLLAMA_USER" 2>/dev/null || printf '%s' "$OLLAMA_USER")
  CLOUDFLARED_GROUP=$(id -gn "$CLOUDFLARED_USER" 2>/dev/null || printf '%s' "$CLOUDFLARED_USER")
  OLLAMA_HOME=$(getent passwd "$OLLAMA_USER" | cut -d: -f6)
  case "$OLLAMA_HOME" in
    ""|"/"|"/nonexistent"|"/root") OLLAMA_HOME="/var/lib/ollama" ;;
  esac
  install -d -o "$OLLAMA_USER" -g "$OLLAMA_GROUP" -m 0750 "$OLLAMA_HOME"
}

ollama_version_text(){
  local bin=$1 ver
  ver=$("$bin" --version 2>/dev/null | grep -Ei 'ollama version|version is [0-9]' | head -1 || true)
  [[ -n "$ver" ]] || ver="binary at $bin"
  printf '%s' "$ver"
}

ollama_bin_path(){
  if command -v ollama >/dev/null 2>&1; then
    command -v ollama
  elif [[ -x /usr/local/bin/ollama ]]; then
    printf '%s\n' "/usr/local/bin/ollama"
  else
    return 1
  fi
}


large_tmp_parent(){
  local candidates=() candidate kb best="" best_kb=0
  if [[ -n "${OLLAMA_TMPDIR:-}" ]]; then
    mkdir -p "$OLLAMA_TMPDIR" 2>/dev/null || return 1
    [[ -w "$OLLAMA_TMPDIR" ]] || return 1
    printf '%s' "$OLLAMA_TMPDIR"
    return 0
  fi
  [[ -n "${TMPDIR:-}" ]] && candidates+=("$TMPDIR")
  candidates+=(/var/tmp /tmp)
  for candidate in "${candidates[@]}"; do
    mkdir -p "$candidate" 2>/dev/null || continue
    [[ -w "$candidate" ]] || continue
    kb=$(df -Pk "$candidate" 2>/dev/null | awk 'NR == 2 { print $4 }')
    [[ "$kb" =~ ^[0-9]+$ ]] || kb=0
    if [[ "$kb" -gt "$best_kb" ]]; then
      best="$candidate"
      best_kb="$kb"
    fi
  done
  [[ -n "$best" ]] || return 1
  printf '%s' "$best"
}

checksum_for_asset(){
  local sums=$1 asset=$2
  awk -v a="$asset" '{ f=$2; sub(/\r$/, "", f); sub(/^\*\/?/, "", f); sub(/^\.\//, "", f); if (f == a) { print $1; exit } }' "$sums"
}

install_ollama_binary(){
  local dpkg_arch tmp_dir archive sums expected actual candidate tmp_parent tmp_kb usr_kb tmp_dev usr_dev
  dpkg_arch=$(dpkg --print-architecture 2>/dev/null || true)
  case "$dpkg_arch" in
    amd64|arm64) ;;
    *) die "Unsupported dpkg architecture for the verified Ollama tarball install: ${dpkg_arch:-unknown} (supported: amd64, arm64)." ;;
  esac

  apt_update
  apt_install curl ca-certificates tar

  tmp_parent=$(large_tmp_parent) || die "Could not find a writable temporary directory. Set OLLAMA_TMPDIR to a directory on a disk with at least 3 GB free."
  tmp_dir=$(mktemp -d "$tmp_parent/ollama-install-XXXXXX") || die "Could not create a temporary directory in $tmp_parent."
  sums="$tmp_dir/sha256sum.txt"
  info "Downloading Ollama checksum list (temporary directory: $tmp_dir)..."
  if ! curl -fsSL --retry 3 "https://github.com/ollama/ollama/releases/latest/download/sha256sum.txt" -o "$sums"; then
    rm -rf "$tmp_dir"
    die "Could not download the Ollama checksum file. Check DNS/network access to GitHub. Refusing to install an unverified archive."
  fi

  local asset=""
  for candidate in "ollama-linux-${dpkg_arch}.tar.zst" "ollama-linux-${dpkg_arch}.tgz" "ollama-linux-${dpkg_arch}.tar.gz"; do
    expected=$(checksum_for_asset "$sums" "$candidate")
    if [[ "$expected" =~ ^[a-f0-9]{64}$ ]]; then
      asset="$candidate"
      break
    fi
  done
  if [[ -z "$asset" ]]; then
    rm -rf "$tmp_dir"
    die "No compatible published Ollama archive found for architecture '$dpkg_arch' in sha256sum.txt."
  fi
  if [[ "$asset" == *.tar.zst ]]; then
    apt_install zstd
  fi

  # Download + extraction together need roughly 3 GB when both live on the
  # same filesystem (compressed archive plus extracted binaries/libraries).
  tmp_kb=$(free_kb "$tmp_parent")
  usr_kb=$(free_kb /usr/local)
  tmp_dev=$(stat -c %d "$tmp_parent" 2>/dev/null || printf '?')
  usr_dev=$(stat -c %d /usr/local 2>/dev/null || printf '?')
  if [[ "$tmp_dev" == "$usr_dev" ]]; then
    if [[ "$tmp_kb" -gt 0 && "$tmp_kb" -lt 3000000 ]]; then
      rm -rf "$tmp_dir"
      die "Not enough free disk space on $tmp_parent for the Ollama download plus extraction (need about 3 GB free). Free space or set OLLAMA_TMPDIR to a larger disk."
    fi
  else
    if [[ "$tmp_kb" -gt 0 && "$tmp_kb" -lt 1700000 ]] || [[ "$usr_kb" -gt 0 && "$usr_kb" -lt 1700000 ]]; then
      rm -rf "$tmp_dir"
      die "Not enough free disk space for Ollama (need about 1.7 GB free in the temp dir and on /usr/local). Check 'df -h'."
    fi
  fi

  archive="$tmp_dir/$asset"
  info "Downloading Ollama release asset: $asset"
  if ! curl -fL --retry 3 "https://github.com/ollama/ollama/releases/latest/download/${asset}" -o "$archive"; then
    rm -rf "$tmp_dir"
    die "Could not download Ollama. This is usually a network/DNS error or not enough free disk space; check 'df -h' and outbound access to GitHub."
  fi
  actual=$(sha256sum "$archive" | awk '{print $1}')
  if [[ "$actual" != "$expected" ]]; then
    rm -rf "$tmp_dir"
    die "Ollama checksum mismatch (expected $expected, got $actual). Aborting."
  fi
  ok "Ollama archive checksum verified (sha256)."

  if ! tar -xaf "$archive" -C /usr/local; then
    rm -rf "$tmp_dir"
    die "Could not extract the Ollama archive into /usr/local (disk full or unsupported archive format)."
  fi
  rm -rf "$tmp_dir"
  hash -r 2>/dev/null || true
  ollama_bin_path >/dev/null || die "Ollama installation failed: binary not found after extraction."
}

ollama_api_ready(){
  curl -fsS http://127.0.0.1:11434/api/version >/dev/null 2>&1
}


is_valid_model_name(){
  [[ "$1" =~ ^[A-Za-z0-9][A-Za-z0-9._/:@-]*$ ]]
}

normalize_model_name(){
  local model=$1 last_part
  last_part=${model##*/}
  if [[ "$last_part" == *:* ]]; then
    printf '%s' "$model"
  else
    printf '%s:latest' "$model"
  fi
}

loaded_model_names(){
  curl -fsS --max-time 10 http://127.0.0.1:11434/api/ps 2>/dev/null \
    | jq -r '.models[]?.name // empty'
}

installed_model_names(){
  curl -fsS --max-time 10 http://127.0.0.1:11434/api/tags 2>/dev/null \
    | jq -r '.models[]?.name // empty'
}

model_names_contain(){
  local names=$1 target=$2 name target_norm
  target_norm=$(normalize_model_name "$target")
  while IFS= read -r name; do
    [[ -n "$name" ]] || continue
    [[ "$(normalize_model_name "$name")" == "$target_norm" ]] && return 0
  done <<< "$names"
  return 1
}

unload_model(){
  local model=$1 payload names i
  is_valid_model_name "$model" || return 1
  payload=$(jq -cn --arg model "$model" '{model:$model, keep_alive:0}') || return 1
  # A runner can take a few seconds to release a model after a request (and
  # can still be busy finishing one). Do not give up after a single unload
  # request: re-send the official keep_alive:0 request while polling /api/ps
  # for about 30 seconds in total.
  for _ in 1 2 3; do
    if curl -fsS --max-time 30 http://127.0.0.1:11434/api/generate \
      -H 'Content-Type: application/json' -d "$payload" >/dev/null 2>&1; then
      for i in $(seq 1 10); do
        names=$(loaded_model_names) || return 1
        model_names_contain "$names" "$model" || return 0
        sleep 1
      done
    else
      names=$(loaded_model_names) || return 1
      model_names_contain "$names" "$model" || return 0
      sleep 2
    fi
  done
  return 1
}

# Unloads every model currently held in RAM except, optionally, one target.
# This frees RAM; it does not delete model files from disk.
stop_loaded_models_except(){
  local target=${1:-} target_norm="__none__" loaded_names loaded
  if [[ -n "$target" ]]; then
    target_norm=$(normalize_model_name "$target")
  fi
  loaded_names=$(loaded_model_names) \
    || die "Could not read the list of models currently loaded in RAM from Ollama. Refusing to switch models blindly."
  while IFS= read -r loaded; do
    [[ -n "$loaded" ]] || continue
    if [[ "$(normalize_model_name "$loaded")" != "$target_norm" ]]; then
      info "Unloading current model from RAM first: $loaded"
      unload_model "$loaded" \
        || die "Could not unload the currently loaded model: $loaded. It may be busy; try again in a moment."
      ok "Model unloaded from RAM: $loaded"
    fi
  done <<< "$loaded_names"
}

# Softer variant for benchmark / speed-apply sequences: if a model stays in
# RAM after the retried unload (for example because it is still finishing a
# request), warn and continue the sequence instead of aborting everything.
# The next request still asks Ollama for the target model, and the server is
# configured with OLLAMA_MAX_LOADED_MODELS=1. Strict callers (model switch,
# deletion, setup) keep using stop_loaded_models_except above.
stop_loaded_models_except_soft(){
  local target=$1 target_norm loaded_names loaded
  target_norm=$(normalize_model_name "$target")
  loaded_names=$(loaded_model_names) \
    || die "Could not read the list of models currently loaded in RAM from Ollama. Refusing to continue blindly."
  while IFS= read -r loaded; do
    [[ -n "$loaded" ]] || continue
    if [[ "$(normalize_model_name "$loaded")" != "$target_norm" ]]; then
      info "Unloading current model from RAM first: $loaded"
      if unload_model "$loaded"; then
        ok "Model unloaded from RAM: $loaded"
      else
        warn "Could not unload $loaded from RAM after repeated attempts (it may still be busy). Continuing the sequence: the next request will ask Ollama for $target, and Ollama is limited to one loaded model."
      fi
    fi
  done <<< "$loaded_names"
  return 0
}

pull_model_with_retry(){
  local model=$1 ollama_bin=$2 models_kb pull_attempt
  models_kb=$(free_kb "$OLLAMA_HOME")
  if [[ "$models_kb" -gt 0 && "$models_kb" -lt 2000000 ]]; then
    warn "Less than about 2 GB free on $OLLAMA_HOME. A larger model may fail while pulling; free disk space if needed."
  fi
  info "Pulling model $model (this may take a while)..."
  for pull_attempt in 1 2; do
    if "$ollama_bin" pull "$model"; then
      return 0
    fi
    if [[ "$pull_attempt" -eq 2 ]]; then
      die "Failed to pull Ollama model: $model (check network, disk space and the exact model name)."
    fi
    warn "Model pull failed (attempt 1/2); retrying in 5 seconds..."
    sleep 5
  done
}

show_loaded_models(){
  local names
  if ! names=$(loaded_model_names); then
    die "Ollama API is not answering, so loaded models cannot be listed. Try: ola recover"
  fi
  if [[ -z "$names" ]]; then
    echo "No model is currently loaded in RAM."
  else
    echo "Models currently loaded in RAM:"
    printf '%s\n' "$names"
  fi
}

unload_models_command(){
  local target=${1:-} loaded_names
  require_commands curl jq
  ollama_api_ready || die "Ollama API is not answering. Try: ola recover"
  if [[ -n "$target" ]]; then
    is_valid_model_name "$target" || die "Invalid model name: $target"
    loaded_names=$(loaded_model_names) || die "Could not list loaded models."
    if ! model_names_contain "$loaded_names" "$target"; then
      ok "Model is not currently loaded in RAM: $target"
      return 0
    fi
    info "Unloading model from RAM: $target"
    unload_model "$target" || die "Could not unload model: $target"
    ok "Model unloaded from RAM: $target"
  else
    stop_loaded_models_except ""
    ok "All loaded models have been unloaded from RAM. The Ollama service itself is still running."
  fi
}



format_model_size(){
  local bytes=${1:-0}
  if [[ ! "$bytes" =~ ^[0-9]+$ ]] || [[ "$bytes" -eq 0 ]]; then
    printf '%s' "taille inconnue"
  elif [[ "$bytes" -ge 1073741824 ]]; then
    awk -v b="$bytes" 'BEGIN { printf "%.1f GB", b / 1073741824 }'
  elif [[ "$bytes" -ge 1048576 ]]; then
    awk -v b="$bytes" 'BEGIN { printf "%.1f MB", b / 1048576 }'
  elif [[ "$bytes" -ge 1024 ]]; then
    awk -v b="$bytes" 'BEGIN { printf "%.1f KB", b / 1024 }'
  else
    printf '%s B' "$bytes"
  fi
}

read_model_action(){
  local -n _action_ref=$1
  local raw=""
  _action_ref=""
  # Read a whole line (key + Enter), not a single raw character: with a PTY,
  # Bash single-character reads can lose already-typed input after external
  # commands run. A line-based read is the reliable interactive behaviour.
  if ! IFS= read -r -p "Action (u utiliser, d supprimer, l libérer RAM, a ajouter+utiliser, r rafraîchir, q quitter, puis Entrée) : " raw; then
    return 1
  fi
  _action_ref=${raw:0:1}
}

read_manager_value(){
  local -n _value_ref=$1
  local prompt=$2 default=${3-}
  local value
  _value_ref=""
  if ! IFS= read -r -p "$prompt" value; then
    return 1
  fi
  _value_ref=${value:-$default}
}

selected_model_from_prompt(){
  local -n _selected_ref=$1
  local idx=""
  _selected_ref=""
  if ! read_manager_value idx "Numéro du modèle : " ""; then
    return 1
  fi
  [[ "$idx" =~ ^[0-9]+$ ]] || return 1
  [[ "$idx" -ge 1 && "$idx" -le ${#MODEL_MANAGER_NAMES[@]} ]] || return 1
  _selected_ref=${MODEL_MANAGER_NAMES[$((idx - 1))]}
}

model_manager(){
  local tags_json loaded_names current_default rows name size markers action selected prereqs_done=0 i
  require_commands curl jq
  while true; do
    if ! tags_json=$(curl -fsS --max-time 10 http://127.0.0.1:11434/api/tags 2>/dev/null); then
      die "Ollama API is not answering, so models cannot be managed. Try: ola recover"
    fi
    loaded_names=$(loaded_model_names 2>/dev/null || true)
    current_default=$(saved_model_name)
    MODEL_MANAGER_NAMES=()
    local model_sizes=()
    rows=$(printf '%s' "$tags_json" | jq -r '.models[]? | [.name, ((.size // 0) | tostring)] | @tsv' 2>/dev/null || true)
    while IFS=$'\t' read -r name size; do
      [[ -n "$name" ]] || continue
      MODEL_MANAGER_NAMES+=("$name")
      model_sizes+=("${size:-0}")
    done <<< "$rows"

    echo
    echo "================ Modèles Ollama ================"
    if [[ ${#MODEL_MANAGER_NAMES[@]} -eq 0 ]]; then
      echo "Aucun modèle téléchargé pour le moment."
    else
      for i in "${!MODEL_MANAGER_NAMES[@]}"; do
        markers=""
        if [[ "$(normalize_model_name "${MODEL_MANAGER_NAMES[$i]}")" == "$(normalize_model_name "$current_default")" ]]; then
          markers="$markers [défaut]"
        fi
        if model_names_contain "$loaded_names" "${MODEL_MANAGER_NAMES[$i]}"; then
          markers="$markers [RAM]"
        fi
        printf '%2d) %-32s %14s%s\n' "$((i + 1))" "${MODEL_MANAGER_NAMES[$i]}" "$(format_model_size "${model_sizes[$i]}")" "$markers"
      done
    fi
    echo "--------------------------------------------------"
    echo "u = utiliser    d = supprimer    l = libérer la RAM"
    echo "a = ajouter + utiliser un autre modèle"
    echo "r = rafraîchir  q = quitter"
    if [[ $EUID -ne 0 ]]; then
      echo "Mode lecture seule : lance ola models en root pour utiliser/supprimer."
    fi

    if ! read_model_action action; then
      echo
      break
    fi
    action=${action,,}

    case "$action" in
      q|"")
        [[ "$action" == "q" ]] && break
        ;;
      r)
        ;;
      a)
        if [[ $EUID -ne 0 ]]; then
          warn "Root requis pour ajouter/utiliser un modèle. Relance : sudo ola models"
          continue
        fi
        if [[ "$prereqs_done" -eq 0 ]]; then
          install_ola_command < /dev/null
          require_supervisor_running < /dev/null
          ensure_watchdog < /dev/null
          prereqs_done=1
        fi
        if ! read_manager_value selected "Nom du modèle à télécharger et utiliser : " ""; then
          warn "Ajout annulé."
          continue
        fi
        [[ -n "$selected" ]] || { warn "Nom de modèle vide; ajout annulé."; continue; }
        switch_model "$selected" < /dev/null
        ;;
      u|d|l)
        if [[ ${#MODEL_MANAGER_NAMES[@]} -eq 0 ]]; then
          warn "Aucun modèle à gérer. Utilise 'a' pour en ajouter un."
          continue
        fi
        if ! selected_model_from_prompt selected; then
          warn "Numéro invalide; action annulée."
          continue
        fi
        if [[ $EUID -ne 0 ]]; then
          warn "Root requis pour cette action. Relance : sudo ola models"
          continue
        fi
        if [[ "$prereqs_done" -eq 0 ]]; then
          install_ola_command < /dev/null
          require_supervisor_running < /dev/null
          ensure_watchdog < /dev/null
          prereqs_done=1
        fi
        case "$action" in
          u)
            switch_model "$selected" < /dev/null
            ;;
          l)
            unload_models_command "$selected" < /dev/null
            ;;
          d)
            if [[ "$(normalize_model_name "$current_default")" == "$(normalize_model_name "$selected")" ]]; then
              delete_model_command "$selected" 1 < /dev/null
            else
              delete_model_command "$selected" 0 < /dev/null
            fi
            ;;
        esac
        ;;
      *)
        warn "Action inconnue : $action"
        ;;
    esac
  done
}

show_installed_models(){
  local names
  require_commands curl jq
  if ! names=$(installed_model_names); then
    die "Ollama API is not answering, so installed models cannot be listed. Try: ola recover"
  fi
  if [[ -z "$names" ]]; then
    echo "No model is currently downloaded on disk."
  else
    echo "Models currently downloaded on disk:"
    printf '%s\n' "$names"
  fi
}

delete_model_command(){
  local target=$1 force=${2:-0} ollama_bin installed_names loaded_names current_default payload remaining new_default i
  is_valid_model_name "$target" || die "Invalid model name: $target (example: qwen3:1.7b)"
  require_commands curl jq
  ollama_bin=$(ollama_bin_path) || die "Ollama binary not found. Run setup first: ola setup"

  if ! supervisor_program_running ollama; then
    info "Ollama is not RUNNING; starting it before deleting the model..."
    supervisor_ctl start ollama 2>/dev/null || supervisor_ctl restart ollama \
      || die "Could not start Ollama. Check: ola logs"
    wait_for_supervisor_program ollama 30 || die "Ollama did not reach RUNNING. Check: ola logs"
  fi
  ollama_api_ready || die "Ollama API is not answering. Try: ola recover"

  installed_names=$(installed_model_names) \
    || die "Could not read the installed model list from Ollama."
  if ! model_names_contain "$installed_names" "$target"; then
    ok "Model is not downloaded on disk: $target"
    return 0
  fi

  current_default=$(saved_model_name)
  if [[ "$(normalize_model_name "$current_default")" == "$(normalize_model_name "$target")" && "$force" -ne 1 ]]; then
    die "Refusing to delete the current default model '$target'. Switch first with: ola use <another-model> — or force it with: ola delete $target --force"
  fi

  loaded_names=$(loaded_model_names) || die "Could not list models loaded in RAM."
  if model_names_contain "$loaded_names" "$target"; then
    info "Model is loaded in RAM; unloading it before disk deletion: $target"
    unload_model "$target" \
      || die "Could not unload model $target from RAM. It may be busy; try again in a moment."
    ok "Model unloaded from RAM: $target"
  fi

  warn "Permanently deleting model from disk: $target"
  payload=$(jq -cn --arg model "$target" '{model:$model}') || die "Could not build the model deletion request."
  if ! curl -fsS --max-time 60 -X DELETE http://127.0.0.1:11434/api/delete \
    -H 'Content-Type: application/json' -d "$payload" >/dev/null 2>&1; then
    warn "The Ollama delete API did not accept the request; trying the Ollama CLI fallback..."
    "$ollama_bin" rm "$target" \
      || die "Could not delete model: $target. Check the exact name with: ola models"
  fi

  for i in $(seq 1 30); do
    installed_names=$(installed_model_names) || die "Could not verify model deletion."
    model_names_contain "$installed_names" "$target" || break
    if [[ "$i" -eq 30 ]]; then
      die "Model $target still appears in the installed list after deletion. Check: ola logs"
    fi
    sleep 1
  done

  if [[ "$(normalize_model_name "$current_default")" == "$(normalize_model_name "$target")" ]]; then
    remaining=$(installed_model_names) || die "Model deleted, but the remaining model list could not be read."
    if [[ -n "$remaining" ]]; then
      new_default=$(printf '%s\n' "$remaining" | head -n 1)
      printf '%s\n' "$new_default" > "$MODEL_FILE" \
        || die "Model deleted, but the new default model could not be saved."
      chmod 600 "$MODEL_FILE" || die "Could not set permissions on $MODEL_FILE."
      warn "Default model was deleted; the new default is: $new_default"
    else
      rm -f "$MODEL_FILE"
      warn "Default model was deleted and no downloaded model remains. Install one with: ola use <model>"
    fi
  fi
  ok "Model permanently deleted from disk: $target"
}

switch_model(){
  local target=$1 ollama_bin installed_names loaded_names payload response content mem_kb
  is_valid_model_name "$target" || die "Invalid model name: $target (example: qwen3:1.7b)"
  require_commands curl jq
  ollama_bin=$(ollama_bin_path) || die "Ollama binary not found. Run setup first: ola setup"
  ensure_service_users

  if ! supervisor_program_running ollama; then
    info "Ollama is not RUNNING; starting it before switching models..."
    supervisor_ctl start ollama 2>/dev/null || supervisor_ctl restart ollama \
      || die "Could not start Ollama. Check: ola logs"
    wait_for_supervisor_program ollama 30 || die "Ollama did not reach RUNNING. Check: ola logs"
  fi
  ollama_api_ready || die "Ollama API is not answering. Try: ola recover"

  info "Switching to model: $target"
  stop_loaded_models_except "$target"

  installed_names=$(installed_model_names) \
    || die "Could not read the installed model list from Ollama."
  if model_names_contain "$installed_names" "$target"; then
    ok "Model already downloaded: $target"
  else
    pull_model_with_retry "$target" "$ollama_bin"
  fi

  # Pulling does not load a model, but stop again in case another request
  # loaded a different model while the download was running.
  stop_loaded_models_except "$target"
  loaded_names=$(loaded_model_names) || die "Could not verify loaded models after download."
  if model_names_contain "$loaded_names" "$target"; then
    ok "Model already loaded in RAM: $target"
  else
    info "Loading model into RAM: $target"
    payload=$(jq -cn --arg model "$target" '{model:$model, messages:[{role:"user", content:"Reply only with OK."}], stream:false}') \
      || die "Could not build the model loading request."
    if ! response=$(curl -fsS --max-time 180 http://127.0.0.1:11434/api/chat \
      -H 'Content-Type: application/json' -d "$payload" 2>/dev/null); then
      die "Model $target was downloaded but could not be loaded. Check RAM and: ola logs"
    fi
    content=$(printf '%s' "$response" | jq -r '.message.content // .response // empty' 2>/dev/null || true)
    ok "Model loaded and answered: ${content:-OK}"
  fi

  stop_loaded_models_except "$target"
  loaded_names=$(loaded_model_names) || die "Could not verify the final loaded model list."
  model_names_contain "$loaded_names" "$target" \
    || die "Model $target did not remain loaded. Check: ola logs"

  printf '%s\n' "$target" > "$MODEL_FILE" || die "Could not save the default model to $MODEL_FILE."
  chmod 600 "$MODEL_FILE" || die "Could not set permissions on $MODEL_FILE."
  mem_kb=$(awk '/^MemAvailable:/ { print $2 }' /proc/meminfo 2>/dev/null || true)
  ok "Default model is now: $target (previous models were unloaded from RAM, not deleted from disk)."
  if [[ "$mem_kb" =~ ^[0-9]+$ ]]; then
    info "Available RAM now: about $((mem_kb / 1024)) MB"
  fi
}

stop_unmanaged_ollama(){
  local ollama_bin=$1 expected_exe pid exe cmdline unknown=0 i pid_list p
  supervisor_program_running ollama && return 0
  expected_exe=$(readlink -f "$ollama_bin" 2>/dev/null || printf '%s' "$ollama_bin")

  local pids=()
  # Do not use Bash process substitution here: some minimal containers do not
  # provide /dev/fd, which made the previous mapfile line abort the setup.
  pid_list=$(ollama_pids)
  # shellcheck disable=SC2086 # ollama_pids prints a list of numeric PIDs.
  for p in $pid_list; do pids+=("$p"); done
  if [[ ${#pids[@]} -eq 0 ]]; then
    if ollama_api_ready; then
      die "Something is answering on 127.0.0.1:11434 but no Ollama process was found. Free the port or stop that service, then re-run setup."
    fi
    return 0
  fi

  for pid in "${pids[@]}"; do
    exe=$(readlink -f "/proc/$pid/exe" 2>/dev/null || true)
    cmdline=$(tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null || true)
    if [[ "$exe" == "$expected_exe" && "$cmdline" == *"$ollama_bin serve"* ]]; then
      warn "Stopping the unmanaged Ollama process $pid so Supervisor can manage it."
      kill -TERM "$pid" 2>/dev/null || true
    else
      warn "Not killing Ollama-like process $pid automatically (binary/cmdline not verified: ${exe:-unknown})."
      unknown=1
    fi
  done

  for i in $(seq 1 15); do
    if ! ollama_api_ready && ! any_ollama_process; then
      return 0
    fi
    sleep 1
  done

  if ollama_api_ready || any_ollama_process; then
    if [[ "$unknown" -eq 1 ]]; then
      die "An unverified process is still using Ollama/port 11434. Stop it manually, then re-run setup."
    fi
    die "The previous Ollama process did not stop in time. Stop it manually, then re-run setup."
  fi
}

# Pack Speed mode is persisted in SPEED_FILE ("balanced" or "speed") so a
# later setup keeps the choice. "balanced" is exactly the historical
# configuration. "speed" only adds Flash Attention and a q8_0 KV cache; it
# deliberately never raises OLLAMA_NUM_PARALLEL, OLLAMA_MAX_LOADED_MODELS or
# the context length, which would cost RAM on small sandboxes.
saved_speed_mode(){
  local mode=""
  if [[ -r "$SPEED_FILE" ]]; then
    mode=$(head -n 1 "$SPEED_FILE" 2>/dev/null || true)
  fi
  case "$mode" in
    speed) printf '%s' "speed" ;;
    *) printf '%s' "balanced" ;;
  esac
}

save_speed_mode(){
  local mode=$1
  printf '%s\n' "$mode" > "$SPEED_FILE" || die "Could not save the speed mode to $SPEED_FILE."
  chmod 600 "$SPEED_FILE" || die "Could not set permissions on $SPEED_FILE."
}

# Server-wide OLLAMA_KEEP_ALIVE default, persisted in KEEPALIVE_FILE so a
# later setup keeps the choice. "5m" is exactly Ollama's historical default
# and frees RAM sooner; a longer value keeps one model warm (faster first
# token) but holds its RAM. Only applied to the Supervisor config by
# "ola fluid keepalive"; it never raises the model/parallel counts.
is_valid_keep_alive(){
  local value=$1
  [[ -n "$value" ]] || return 1
  [[ "$value" == "-1" ]] && return 0
  [[ "$value" =~ ^[0-9]+$ ]] && return 0
  [[ "$value" =~ ^([0-9]+h)?([0-9]+m)?([0-9]+s)?$ ]]
}

saved_keep_alive(){
  local value=""
  if [[ -r "$KEEPALIVE_FILE" ]]; then
    value=$(head -n 1 "$KEEPALIVE_FILE" 2>/dev/null || true)
  fi
  if is_valid_keep_alive "$value"; then
    printf '%s' "$value"
  else
    printf '%s' "5m"
  fi
}

save_keep_alive(){
  local value=$1
  printf '%s\n' "$value" > "$KEEPALIVE_FILE" || die "Could not save the keep-alive default to $KEEPALIVE_FILE."
  chmod 600 "$KEEPALIVE_FILE" || die "Could not set permissions on $KEEPALIVE_FILE."
}

ollama_environment_line(){
  local mode=$1 env
  env="OLLAMA_HOST=\"127.0.0.1:11434\",OLLAMA_ORIGINS=\"*\",OLLAMA_CONTEXT_LENGTH=\"$OLLAMA_CONTEXT_LENGTH\",OLLAMA_KEEP_ALIVE=\"$(saved_keep_alive)\",OLLAMA_MAX_LOADED_MODELS=\"1\",OLLAMA_NUM_PARALLEL=\"1\""
  if [[ "$mode" == "speed" ]]; then
    env="${env},OLLAMA_FLASH_ATTENTION=\"1\",OLLAMA_KV_CACHE_TYPE=\"q8_0\""
  fi
  env="${env},HOME=\"$OLLAMA_HOME\""
  printf '%s' "$env"
}

write_ollama_supervisor_config(){
  local ollama_bin=$1 mode=$2 env_line
  env_line=$(ollama_environment_line "$mode")
  cat > "$SUP_DIR/ollama.conf" <<EOF
[program:ollama]
command=$ollama_bin serve
user=$OLLAMA_USER
environment=$env_line
autostart=true
autorestart=true
startsecs=5
startretries=10
stopsignal=TERM
stopasgroup=true
killasgroup=true
stdout_logfile=/var/log/supervisor/ollama.log
stdout_logfile_maxbytes=10MB
stdout_logfile_backups=3
stderr_logfile=/var/log/supervisor/ollama-error.log
stderr_logfile_maxbytes=10MB
stderr_logfile_backups=3
EOF
  chmod 600 "$SUP_DIR/ollama.conf"
}

# Reads one OLLAMA_* value from the generated Supervisor config. Prints an
# empty string when the file or the key is unavailable (for example when a
# non-root user cannot read the root-only config file).
ollama_config_value(){
  local key=$1 file="$SUP_DIR/ollama.conf" line
  [[ -r "$file" ]] || return 0
  line=$(grep '^environment=' "$file" 2>/dev/null | head -n 1 || true)
  [[ -n "$line" ]] || return 0
  printf '%s' "$line" | tr ',' '\n' | sed -n "s/^${key}=\"\\(.*\\)\"$/\\1/p" | head -n 1
}

speed_config_matches(){
  local mode=$1 flash
  [[ -r "$SUP_DIR/ollama.conf" ]] || return 1
  flash=$(ollama_config_value OLLAMA_FLASH_ATTENTION)
  if [[ "$mode" == "speed" ]]; then
    [[ "$flash" == "1" ]] || return 1
    [[ "$(ollama_config_value OLLAMA_KV_CACHE_TYPE)" == "q8_0" ]] || return 1
  else
    [[ -z "$flash" ]] || return 1
    [[ -z "$(ollama_config_value OLLAMA_KV_CACHE_TYPE)" ]] || return 1
  fi
  return 0
}

cpu_logical_cores(){
  local n
  n=$(nproc 2>/dev/null || printf '%s' "1")
  [[ "$n" =~ ^[0-9]+$ && "$n" -ge 1 ]] || n=1
  printf '%s' "$n"
}

cpu_physical_cores(){
  local logical per sockets cores
  logical=$(cpu_logical_cores)
  per=""
  sockets=""
  if command -v lscpu >/dev/null 2>&1; then
    per=$(lscpu 2>/dev/null | awk -F: '/^Core\(s\) per socket:/ { v=$2; gsub(/[[:space:]]/, "", v); print v; exit }')
    sockets=$(lscpu 2>/dev/null | awk -F: '/^Socket\(s\):/ { v=$2; gsub(/[[:space:]]/, "", v); print v; exit }')
  fi
  if [[ "$per" =~ ^[0-9]+$ && "$sockets" =~ ^[0-9]+$ ]]; then
    cores=$((per * sockets))
    if [[ "$cores" -ge 1 && "$cores" -le "$logical" ]]; then
      printf '%s' "$cores"
      return 0
    fi
  fi
  per=$(awk -F: '/^cpu cores/ { v=$2; gsub(/[[:space:]]/, "", v); print v; exit }' /proc/cpuinfo 2>/dev/null || true)
  if [[ "$per" =~ ^[0-9]+$ && "$per" -ge 1 && "$per" -le "$logical" ]]; then
    printf '%s' "$per"
    return 0
  fi
  printf '%s' "$logical"
}

cpu_speed_summary(){
  local flags
  flags=$(awk -F: '/^flags/ { print $2; exit }' /proc/cpuinfo 2>/dev/null || true)
  case " $flags " in
    *" avx512f "*) printf '%s' "AVX-512 détecté (meilleur backend CPU Ollama attendu)" ;;
    *" avx2 "*) printf '%s' "AVX2 détecté (bon backend CPU Ollama : cpu_avx2)" ;;
    *" avx "*) printf '%s' "AVX détecté, sans AVX2 (backend CPU Ollama intermédiaire)" ;;
    *) printf '%s' "ni AVX2 ni AVX détectés (backend CPU générique, plus lent)" ;;
  esac
}

install_ollama(){
  local ollama_bin
  if ollama_bin=$(ollama_bin_path); then
    ok "Ollama already installed: $(ollama_version_text "$ollama_bin")"
  else
    info "Installing Ollama from the checksum-verified GitHub release archive..."
    install_ollama_binary
    ollama_bin=$(ollama_bin_path) || die "Ollama binary not found after installation."
    ok "Ollama installed: $(ollama_version_text "$ollama_bin")"
  fi

  ensure_service_users

  # The tunnel deliberately exposes Ollama without Cloudflare Access. Ollama
  # has two separate 403 guards: OLLAMA_ORIGINS controls browser Origin
  # headers, while its Host check rejects public tunnel hostnames. The
  # origin allow-list is opened here, and cloudflared rewrites the Host
  # header to localhost:11434 in both tunnel modes below.
  write_ollama_supervisor_config "$ollama_bin" "$(saved_speed_mode)"
  if [[ "$(saved_speed_mode)" == "speed" ]]; then
    info "Pack Speed is enabled for Ollama (Flash Attention + q8_0 KV cache; context and parallel requests unchanged)."
  fi
  if [[ "$(saved_keep_alive)" != "5m" ]]; then
    info "Fluid keep-alive default is kept: OLLAMA_KEEP_ALIVE=$(saved_keep_alive) (saved in $KEEPALIVE_FILE)."
  fi

  stop_unmanaged_ollama "$ollama_bin"
  supervisor_apply
  supervisor_ctl start ollama 2>/dev/null || true

  local i
  for i in $(seq 1 30); do
    if supervisor_program_running ollama && ollama_api_ready; then
      break
    fi
    if [[ "$i" -eq 30 ]]; then
      die "Ollama API did not start under Supervisor. Check $LOG_DIR/ollama-error.log"
    fi
    sleep 1
  done
  ok "Ollama is running under Supervisor ($OLLAMA_USER) and answers on 127.0.0.1:11434."

  local model
  if ! model=$(prompt_value "Ollama model [$MODEL_DEFAULT]: " "$MODEL_DEFAULT"); then
    die "No input received for the Ollama model; aborting instead of silently using the default."
  fi
  is_valid_model_name "$model" || die "Invalid Ollama model name: $model"
  stop_loaded_models_except "$model"
  pull_model_with_retry "$model" "$ollama_bin"
  printf '%s\n' "$model" > "$MODEL_FILE"
  chmod 600 "$MODEL_FILE"
  ok "Model ready: $model"
}

install_cloudflared_github_verified(){
  if command -v cloudflared >/dev/null; then
    ok "cloudflared already installed: $(cloudflared --version 2>&1 | head -1)"
    return
  fi
  apt_update
  apt_install curl ca-certificates jq
  local arch asset tmp_deb tmp_json expected actual dpkg_status
  case "$(dpkg --print-architecture)" in
    amd64) arch=amd64 ;;
    arm64) arch=arm64 ;;
    armhf) arch=arm ;;
    *) die "Unsupported dpkg architecture: $(dpkg --print-architecture)" ;;
  esac
  asset="cloudflared-linux-${arch}.deb"
  local tmp_parent
  tmp_parent=$(large_tmp_parent || printf '%s' "/tmp")
  tmp_deb="$(mktemp "$tmp_parent/cloudflared-XXXXXX.deb")"
  tmp_json="$(mktemp "$tmp_parent/cloudflared-release-XXXXXX.json")"
  info "Downloading Cloudflare cloudflared package for $arch..."

  if ! curl -fsSL "https://api.github.com/repos/cloudflare/cloudflared/releases/latest" -o "$tmp_json"; then
    rm -f "$tmp_deb" "$tmp_json"
    die "Could not read the cloudflared release metadata from GitHub. Refusing to install without a checksum."
  fi
  expected=$(jq -r --arg name "$asset" '.assets[]? | select(.name == $name) | (.digest // empty)' "$tmp_json" 2>/dev/null | sed -n 's/^sha256://p' | head -1)
  rm -f "$tmp_json"
  if [[ ! "$expected" =~ ^[a-f0-9]{64}$ ]]; then
    rm -f "$tmp_deb"
    die "No published SHA-256 available via the GitHub API for $asset. Refusing to install an unverified package as root."
  fi
  if ! curl -fL --retry 3 "https://github.com/cloudflare/cloudflared/releases/latest/download/${asset}" -o "$tmp_deb"; then
    rm -f "$tmp_deb"
    die "Could not download cloudflared. Check outbound network access to GitHub."
  fi
  actual=$(sha256sum "$tmp_deb" | awk '{print $1}')
  if [[ "$actual" != "$expected" ]]; then
    rm -f "$tmp_deb"
    die "cloudflared checksum mismatch (expected $expected, got $actual). Aborting."
  fi
  ok "cloudflared package checksum verified (sha256)."

  dpkg_status=0
  dpkg -i "$tmp_deb" || dpkg_status=1
  if [[ "$dpkg_status" -ne 0 ]]; then
    apt_install -f || dpkg_status=1
    dpkg -i "$tmp_deb" || dpkg_status=1
  fi
  rm -f "$tmp_deb"
  [[ "$dpkg_status" -eq 0 ]] || die "cloudflared package installation failed."
  command -v cloudflared >/dev/null || die "cloudflared installation failed."
  ok "$(cloudflared --version 2>&1 | head -1)"
}


install_cloudflared_official_repo(){
  if command -v cloudflared >/dev/null; then
    return 0
  fi
  apt_install curl gnupg ca-certificates apt-transport-https || return 1
  install -d -m 0755 /usr/share/keyrings || return 1
  info "Adding the official Cloudflare apt repository..."
  if ! curl -fsSL "https://pkg.cloudflare.com/cloudflare-main.gpg" | gpg --batch --yes --dearmor -o /usr/share/keyrings/cloudflare-main.gpg; then
    return 1
  fi
  chmod 644 /usr/share/keyrings/cloudflare-main.gpg || return 1
  printf '%s\n' "deb [signed-by=/usr/share/keyrings/cloudflare-main.gpg] https://pkg.cloudflare.com/cloudflared any main" \
    | tee /etc/apt/sources.list.d/cloudflared.list >/dev/null || return 1
  apt_update || return 1
  apt_install cloudflared || return 1
  command -v cloudflared >/dev/null
}

install_cloudflared(){
  if command -v cloudflared >/dev/null; then
    ok "cloudflared already installed: $(cloudflared --version 2>&1 | head -1)"
    return
  fi
  info "Trying the official Cloudflare apt repository first..."
  if install_cloudflared_official_repo; then
    ok "cloudflared installed: $(cloudflared --version 2>&1 | head -1)"
    return
  fi
  warn "The official Cloudflare repository method failed. Falling back to the verified GitHub .deb..."
  install_cloudflared_github_verified
}

file_size(){
  local f=$1
  [[ -f "$f" ]] || { printf '0'; return; }
  stat -c %s "$f" 2>/dev/null || printf '0'
}

new_log_content(){
  local f=$1 offset=$2 size
  [[ -f "$f" ]] || return 0
  size=$(file_size "$f")
  if [[ "$size" -lt "$offset" ]]; then
    offset=0
  fi
  tail -c "+$((offset + 1))" "$f" 2>/dev/null || true
}

wait_for_supervisor_program(){
  local program=$1 seconds=$2 i
  for i in $(seq 1 "$seconds"); do
    if supervisor_program_running "$program"; then
      return 0
    fi
    sleep 1
  done
  return 1
}

configure_quick_tunnel(){
  info "Configuring a temporary Cloudflare Quick Tunnel..."
  install -d -m 0750 "$LOG_DIR"
  install -d -o root -g "$CLOUDFLARED_GROUP" -m 0750 "$CF_CONF_DIR"
  rm -f "$URL_FILE"
  local cloudflared_bin out_log err_log out_offset err_offset url i protocol_flag=""
  cloudflared_bin=$(command -v cloudflared) || die "cloudflared binary not found."
  if [[ "$CF_TUNNEL_PROTOCOL" != "auto" ]]; then
    protocol_flag=" --protocol=$CF_TUNNEL_PROTOCOL"
  fi
  out_log="$LOG_DIR/cloudflared-ollama.log"
  err_log="$LOG_DIR/cloudflared-ollama-error.log"
  touch "$out_log" "$err_log"
  chmod 600 "$out_log" "$err_log"
  out_offset=$(file_size "$out_log")
  err_offset=$(file_size "$err_log")

  cat > "$SUP_DIR/cloudflared-ollama.conf" <<EOF
[program:cloudflared-ollama]
command=$cloudflared_bin tunnel --no-autoupdate$protocol_flag --url http://127.0.0.1:11434 --http-host-header=localhost:11434
user=$CLOUDFLARED_USER
environment=HOME="$CF_CONF_DIR"
autostart=true
autorestart=true
startsecs=3
startretries=10
stopsignal=TERM
stopasgroup=true
killasgroup=true
stdout_logfile=/var/log/supervisor/cloudflared-ollama.log
stdout_logfile_maxbytes=10MB
stdout_logfile_backups=3
stderr_logfile=/var/log/supervisor/cloudflared-ollama-error.log
stderr_logfile_maxbytes=10MB
stderr_logfile_backups=3
EOF
  chmod 600 "$SUP_DIR/cloudflared-ollama.conf"
  supervisor_apply
  if ! supervisor_ctl restart cloudflared-ollama 2>/dev/null; then
    supervisor_ctl start cloudflared-ollama || die "Could not start the cloudflared Quick Tunnel. Check $err_log"
  fi

  url=""
  for i in $(seq 1 60); do
    if supervisor_program_running cloudflared-ollama; then
      url=$( { new_log_content "$out_log" "$out_offset"; new_log_content "$err_log" "$err_offset"; } \
        | grep -hEo 'https://[[:alnum:]-]+\.trycloudflare\.com' | tail -1 || true )
      if [[ -n "$url" ]] && https_url_ready "${url}/api/version"; then
        break
      fi
    fi
    if [[ "$i" -eq 60 ]]; then
      if [[ -n "$url" ]]; then
        die "Quick Tunnel URL was found ($url) but ${url}/api/version did not answer in time. Check $err_log"
      fi
      die "Quick Tunnel did not produce a verified URL in time. Check $err_log"
    fi
    sleep 1
  done

  printf '%s\n' "$url" > "$URL_FILE"
  chmod 600 "$URL_FILE"
  tighten_log_permissions
  echo
  ok "Quick Tunnel URL: $url"
  echo "API version: ${url}/api/version"
  echo "API chat endpoint: POST ${url}/api/chat"
  warn "Quick Tunnel URLs are temporary and may change after restart. This exposes Ollama without authentication; anyone with the URL can send requests."
}

refresh_named_tunnel_uuid(){
  local tunnel_name=$1 json count
  if ! json=$(cloudflared tunnel list --output json 2>/dev/null); then
    die "Could not list Cloudflare tunnels. Check 'cloudflared tunnel list' and your login."
  fi
  count=$(printf '%s' "$json" | jq -r --arg n "$tunnel_name" '[.[] | select(.name == $n)] | length' 2>/dev/null || printf 'invalid')
  [[ "$count" != "invalid" ]] || die "Could not parse 'cloudflared tunnel list --output json'."
  if [[ "$count" -gt 1 ]]; then
    die "Multiple Cloudflare tunnels are named '$tunnel_name'. Rename/delete the duplicates, then re-run."
  fi
  NAMED_TUNNEL_UUID=$(printf '%s' "$json" | jq -r --arg n "$tunnel_name" '.[] | select(.name == $n) | .id' | head -1)
}

configure_named_tunnel(){
  local tunnel_name hostname uuid source_cred cred_file protocol_line="" candidate_home alt_home
  echo ""
  warn "This mode uses your Cloudflare account and a domain/subdomain. It does not configure Cloudflare Access."
  if ! tunnel_name=$(prompt_value "Tunnel name [ollama-vps]: " "ollama-vps"); then
    die "No input received for the tunnel name; aborting."
  fi
  [[ "$tunnel_name" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$ && "$tunnel_name" != *".."* ]] || die "Invalid tunnel name."
  if ! hostname=$(prompt_value "Public hostname (e.g. ollama.example.com): " ""); then
    die "No input received for the public hostname; aborting."
  fi
  hostname="${hostname,,}"
  is_valid_hostname "$hostname" || die "Invalid hostname."

  ensure_service_users
  if [[ ! -f "$CF_CLI_HOME/cert.pem" ]]; then
    for candidate_home in "/root/.cloudflared" "${HOME:-}/.cloudflared"; do
      if [[ -n "$candidate_home" && "$candidate_home" != "$CF_CLI_HOME" && -f "$candidate_home/cert.pem" ]]; then
        install -d -m 700 "$CF_CLI_HOME"
        install -m 0600 "$candidate_home/cert.pem" "$CF_CLI_HOME/cert.pem"
        info "Using the existing Cloudflare login certificate from $candidate_home."
        break
      fi
    done
  fi
  if [[ ! -f "$CF_CLI_HOME/cert.pem" && -n "${SUDO_USER:-}" ]]; then
    alt_home=$(getent passwd "$SUDO_USER" 2>/dev/null | cut -d: -f6 || true)
    if [[ -n "$alt_home" && -f "$alt_home/.cloudflared/cert.pem" ]]; then
      install -d -m 700 "$CF_CLI_HOME"
      install -m 0600 "$alt_home/.cloudflared/cert.pem" "$CF_CLI_HOME/cert.pem"
      info "Using the existing Cloudflare login certificate from $alt_home/.cloudflared."
    fi
  fi
  rm -f "$URL_FILE"
  install -d -m 700 "$CF_CLI_HOME"
  install -d -o root -g "$CLOUDFLARED_GROUP" -m 0750 "$CF_CONF_DIR"

  if [[ ! -f "$CF_CLI_HOME/cert.pem" ]]; then
    info "Cloudflare will print a login URL. Open it in your browser, sign in, and authorize the domain."
    cloudflared tunnel login || die "Cloudflare login failed or was cancelled. Re-run setup and complete the browser authorization."
  fi
  [[ -f "$CF_CLI_HOME/cert.pem" ]] || die "Cloudflare login certificate not found at $CF_CLI_HOME/cert.pem"
  chmod 600 "$CF_CLI_HOME/cert.pem"

  refresh_named_tunnel_uuid "$tunnel_name"
  uuid="$NAMED_TUNNEL_UUID"
  if [[ -z "$uuid" ]]; then
    cloudflared tunnel create "$tunnel_name" || die "Could not create Cloudflare tunnel '$tunnel_name'."
    refresh_named_tunnel_uuid "$tunnel_name"
    uuid="$NAMED_TUNNEL_UUID"
  else
    ok "Tunnel '$tunnel_name' already exists."
  fi
  [[ "$uuid" =~ ^[0-9a-fA-F-]{36}$ ]] || die "Could not determine tunnel ID. Check 'cloudflared tunnel list'."
  uuid="${uuid,,}"

  source_cred="$CF_CLI_HOME/${uuid}.json"
  [[ -f "$source_cred" ]] || die "Tunnel credentials missing: $source_cred"
  chmod 600 "$source_cred"
  cred_file="$CF_CONF_DIR/${uuid}.json"
  install -o "$CLOUDFLARED_USER" -g "$CLOUDFLARED_GROUP" -m 0600 "$source_cred" "$cred_file" \
    || die "Could not copy the tunnel credentials into $CF_CONF_DIR for the dedicated cloudflared user."

  if [[ "$CF_TUNNEL_PROTOCOL" != "auto" ]]; then
    protocol_line="protocol: $CF_TUNNEL_PROTOCOL"
  fi
  cat > "$CF_CONF_DIR/config.yml" <<EOF
tunnel: $uuid
credentials-file: $cred_file
no-autoupdate: true
$protocol_line
ingress:
  - hostname: $hostname
    service: http://127.0.0.1:11434
    originRequest:
      httpHostHeader: "localhost:11434"
  - service: http_status:404
EOF
  chown root:"$CLOUDFLARED_GROUP" "$CF_CONF_DIR/config.yml"
  chmod 640 "$CF_CONF_DIR/config.yml"
  cloudflared tunnel --config "$CF_CONF_DIR/config.yml" ingress validate \
    || die "Cloudflare ingress config is invalid: $CF_CONF_DIR/config.yml"

  local cloudflared_bin
  cloudflared_bin=$(command -v cloudflared) || die "cloudflared binary not found."
  cat > "$SUP_DIR/cloudflared-ollama.conf" <<EOF
[program:cloudflared-ollama]
command=$cloudflared_bin tunnel --config $CF_CONF_DIR/config.yml run $uuid
user=$CLOUDFLARED_USER
environment=HOME="$CF_CONF_DIR"
autostart=true
autorestart=true
startsecs=3
startretries=10
stopsignal=TERM
stopasgroup=true
killasgroup=true
stdout_logfile=/var/log/supervisor/cloudflared-ollama.log
stdout_logfile_maxbytes=10MB
stdout_logfile_backups=3
stderr_logfile=/var/log/supervisor/cloudflared-ollama-error.log
stderr_logfile_maxbytes=10MB
stderr_logfile_backups=3
EOF
  chmod 600 "$SUP_DIR/cloudflared-ollama.conf"
  supervisor_apply
  if ! supervisor_ctl restart cloudflared-ollama 2>/dev/null; then
    supervisor_ctl start cloudflared-ollama || die "Could not start the named cloudflared tunnel. Check $LOG_DIR/cloudflared-ollama-error.log"
  fi

  wait_for_supervisor_program cloudflared-ollama 30 \
    || die "The named cloudflared tunnel is not RUNNING under Supervisor. Check $LOG_DIR/cloudflared-ollama-error.log"
  ollama_api_ready || die "Ollama is not answering locally, so the named tunnel cannot be verified."

  cloudflared tunnel route dns "$uuid" "$hostname" \
    || die "Could not create/update the Cloudflare DNS route for $hostname. If a DNS record already exists for this hostname, delete/repoint it in Cloudflare DNS, then re-run setup."

  local i public_url="https://${hostname}" public_verified=0
  info "Waiting up to 2 minutes for ${public_url}/api/version (DNS/Cloudflare propagation)..."
  for i in $(seq 1 60); do
    if https_url_ready "${public_url}/api/version"; then
      public_verified=1
      break
    fi
    if [[ "$i" -eq 20 || "$i" -eq 40 ]]; then
      info "Still waiting for the public hostname to answer..."
    fi
    sleep 2
  done

  printf '%s\n' "$public_url" > "$URL_FILE"
  chmod 600 "$URL_FILE"
  tighten_log_permissions
  if [[ "$public_verified" -eq 1 ]]; then
    ok "Named tunnel configured and verified: $public_url"
  else
    # The connector is RUNNING, ingress was validated and Cloudflare accepted
    # the DNS route. A probe from the same server can still fail because of
    # DNS propagation/cache or hairpin routing, so do not throw away an
    # otherwise working tunnel: save the URL and report the probe honestly.
    warn "Named tunnel is configured and its DNS route was created, but the public probe from this server did not confirm ${public_url}/api/version yet."
    warn "Test it from a browser or another device: ${public_url}/api/version"
    supervisor_ctl status || true
    cloudflared tunnel info "$uuid" 2>/dev/null || true
    if [[ -r "$LOG_DIR/cloudflared-ollama-error.log" ]]; then
      echo "--- Last cloudflared log lines ---"
      tail -n 30 "$LOG_DIR/cloudflared-ollama-error.log" || true
    fi
    ok "Named tunnel configured: $public_url (public answer not yet confirmed from this server)"
  fi
  warn "No Access policy was added. The Ollama API is public at this hostname without authentication."
}

show_status(){
  select_supervisor_paths
  echo "--- Supervisor ---"
  if command -v supervisorctl >/dev/null 2>&1 && [[ -f "$SUP_CONF" ]]; then
    supervisor_ctl status || true
  else
    echo "Supervisor is not installed/configured yet."
  fi
  echo "--- Ollama API ---"
  if command -v curl >/dev/null 2>&1 && curl -fsS http://127.0.0.1:11434/api/version; then
    echo
  else
    echo "Not responding on 127.0.0.1:11434."
  fi
  echo "--- Model ---"
  if command -v ollama >/dev/null 2>&1; then
    ollama list 2>/dev/null || true
  else
    echo "ollama binary not found."
  fi
  echo "--- Public URL ---"
  if [[ -r "$URL_FILE" ]]; then
    cat "$URL_FILE"
    if command -v supervisorctl >/dev/null 2>&1 && [[ -f "$SUP_CONF" ]] && ! supervisor_program_running cloudflared-ollama; then
      echo "(saved URL, but cloudflared-ollama is not RUNNING right now)"
    fi
  elif [[ -f "$URL_FILE" ]]; then
    echo "A URL is saved but is not readable by this user (run status as root)."
  else
    echo "No URL saved yet."
  fi
}

show_logs(){
  local f shown=0
  for f in "$LOG_DIR/cloudflared-ollama.log" "$LOG_DIR/cloudflared-ollama-error.log" "$LOG_DIR/ollama.log" "$LOG_DIR/ollama-error.log"; do
    if [[ -r "$f" ]]; then
      echo "===== $f ====="
      tail -n 40 "$f"
      shown=1
    elif [[ -f "$f" ]]; then
      echo "===== $f ====="
      echo "Not readable by this user (run logs as root)."
      shown=1
    fi
  done
  [[ "$shown" -eq 1 ]] || echo "No supervisor logs found yet in $LOG_DIR."
}

stop_tunnel(){
  supervisor_ctl stop cloudflared-ollama || die "Could not stop cloudflared-ollama. Check Supervisor status and logs."
  rm -f "$URL_FILE"
  ok "Tunnel stopped. Ollama itself is still managed by Supervisor."
}

restart_services(){
  supervisor_ctl restart ollama cloudflared-ollama || die "Could not restart Ollama/cloudflared. Check Supervisor status and logs."
  wait_for_supervisor_program ollama 30 || die "Ollama is not RUNNING after restart."
  if command -v cloudflared >/dev/null 2>&1; then
    wait_for_supervisor_program cloudflared-ollama 30 || die "cloudflared-ollama is not RUNNING after restart."
  fi
  supervisor_ctl status || true
}

saved_model_name(){
  local model=""
  if [[ -r "$MODEL_FILE" ]]; then
    model=$(head -n 1 "$MODEL_FILE" 2>/dev/null || true)
  fi
  [[ -n "$model" ]] || model="$MODEL_DEFAULT"
  printf '%s' "$model"
}

ollama_home_for_status(){
  local home_dir
  home_dir=$(getent passwd "$OLLAMA_USER" 2>/dev/null | cut -d: -f6 || true)
  case "$home_dir" in
    ""|"/"|"/nonexistent"|"/root") home_dir="/var/lib/ollama" ;;
  esac
  printf '%s' "$home_dir"
}

# 0 = cloudflared reports ready, 1 = it definitively reports not ready,
# 2 = the local metrics endpoint is unavailable/unknown. Watchdog and
# recover only act on the definitive "not ready" state, never on "unknown".
cloudflared_ready_state(){
  local code
  code=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 5 http://127.0.0.1:20241/ready 2>/dev/null || true)
  if [[ "$code" == "200" ]]; then
    return 0
  fi
  if [[ -z "$code" || "$code" == "000" ]]; then
    return 2
  fi
  return 1
}

wait_cloudflared_ready(){
  local seconds=$1 i state=2
  [[ "$seconds" =~ ^[0-9]+$ ]] || seconds=30
  for ((i=1; i<=seconds; i++)); do
    state=0
    cloudflared_ready_state || state=$?
    [[ "$state" -eq 0 ]] && return 0
    sleep 1
  done
  return "$state"
}

ensure_watchdog(){
  select_supervisor_paths
  install -d -m 0750 "$LOG_DIR" "$SUP_DIR" \
    || die "Could not create Supervisor directories for the watchdog."
  cat > "$SUP_DIR/ollama-watchdog.conf" <<EOF
[program:ollama-watchdog]
command=$OLA_SCRIPT watchdog-daemon
environment=HOME="/root"
autostart=true
autorestart=true
startsecs=5
startretries=999999
stopsignal=TERM
stopasgroup=true
killasgroup=true
stdout_logfile=/var/log/supervisor/ollama-watchdog.log
stdout_logfile_maxbytes=10MB
stdout_logfile_backups=3
stderr_logfile=/var/log/supervisor/ollama-watchdog-error.log
stderr_logfile_maxbytes=10MB
stderr_logfile_backups=3
EOF
  chmod 600 "$SUP_DIR/ollama-watchdog.conf" \
    || die "Could not set permissions on $SUP_DIR/ollama-watchdog.conf"
  if supervisor_is_running; then
    supervisor_apply
    if supervisor_program_running ollama-watchdog; then
      supervisor_ctl restart ollama-watchdog >/dev/null 2>&1 || true
    else
      supervisor_ctl start ollama-watchdog >/dev/null 2>&1 || true
    fi
  fi
  ok "Health watchdog enabled (checks every ${WATCHDOG_INTERVAL}s; restart after ${WATCHDOG_FAILURES} failed checks)."
}

watchdog_log(){
  printf '%s [watchdog] %s\n' "$(date -u '+%Y-%m-%dT%H:%M:%SZ')" "$*"
}

watchdog_sleep(){
  local seconds=$1 pid
  sleep "$seconds" &
  pid=$!
  wait "$pid" 2>/dev/null || true
}

run_watchdog_daemon(){
  local ollama_failures=0 cloudflared_failures=0 state
  select_supervisor_paths
  case "$WATCHDOG_INTERVAL" in ""|*[!0-9]*) die "Invalid OLA_WATCHDOG_INTERVAL='$WATCHDOG_INTERVAL'." ;; esac
  case "$WATCHDOG_FAILURES" in ""|*[!0-9]*) die "Invalid OLA_WATCHDOG_FAILURES='$WATCHDOG_FAILURES'." ;; esac
  case "$WATCHDOG_COOLDOWN" in ""|*[!0-9]*) die "Invalid OLA_WATCHDOG_COOLDOWN='$WATCHDOG_COOLDOWN'." ;; esac
  [[ "$WATCHDOG_INTERVAL" -ge 10 ]] || die "OLA_WATCHDOG_INTERVAL must be at least 10 seconds."
  [[ "$WATCHDOG_FAILURES" -ge 1 ]] || die "OLA_WATCHDOG_FAILURES must be at least 1."
  [[ "$WATCHDOG_COOLDOWN" -ge 10 ]] || die "OLA_WATCHDOG_COOLDOWN must be at least 10 seconds."
  trap 'exit 0' TERM INT
  watchdog_log "started (interval=${WATCHDOG_INTERVAL}s failures=${WATCHDOG_FAILURES} cooldown=${WATCHDOG_COOLDOWN}s)"
  watchdog_sleep "$WATCHDOG_INTERVAL"
  while true; do
    if [[ -f "$SUP_DIR/ollama.conf" ]] && supervisor_program_running ollama; then
      if ollama_api_ready; then
        ollama_failures=0
      else
        ollama_failures=$((ollama_failures + 1))
        watchdog_log "Ollama API failed health check ${ollama_failures}/${WATCHDOG_FAILURES}."
        if [[ "$ollama_failures" -ge "$WATCHDOG_FAILURES" ]]; then
          watchdog_log "restarting Ollama after repeated API failures."
          supervisor_ctl restart ollama || watchdog_log "ERROR: Supervisor could not restart Ollama."
          ollama_failures=0
          watchdog_sleep "$WATCHDOG_COOLDOWN"
          continue
        fi
      fi
    else
      ollama_failures=0
    fi

    if [[ -f "$SUP_DIR/cloudflared-ollama.conf" ]] && supervisor_program_running cloudflared-ollama; then
      state=0
      cloudflared_ready_state || state=$?
      if [[ "$state" -eq 0 ]]; then
        cloudflared_failures=0
      elif [[ "$state" -eq 1 ]]; then
        cloudflared_failures=$((cloudflared_failures + 1))
        watchdog_log "cloudflared failed readiness check ${cloudflared_failures}/${WATCHDOG_FAILURES}."
        if [[ "$cloudflared_failures" -ge "$WATCHDOG_FAILURES" ]]; then
          watchdog_log "restarting cloudflared after repeated readiness failures."
          supervisor_ctl restart cloudflared-ollama || watchdog_log "ERROR: Supervisor could not restart cloudflared."
          cloudflared_failures=0
          watchdog_sleep "$WATCHDOG_COOLDOWN"
          continue
        fi
      else
        cloudflared_failures=0
      fi
    else
      cloudflared_failures=0
    fi
    watchdog_sleep "$WATCHDOG_INTERVAL"
  done
}

show_watchdog(){
  select_supervisor_paths
  echo "--- Health watchdog ---"
  if [[ -f "$SUP_DIR/ollama-watchdog.conf" ]]; then
    echo "Config: $SUP_DIR/ollama-watchdog.conf"
  else
    echo "Not installed yet. Run: ola start (or a full setup)."
    return 0
  fi
  if command -v supervisorctl >/dev/null 2>&1 && [[ -f "$SUP_CONF" ]]; then
    supervisor_ctl status ollama-watchdog 2>/dev/null || echo "ollama-watchdog is not RUNNING."
  else
    echo "Supervisor is not installed/configured yet."
  fi
  local f
  for f in "$LOG_DIR/ollama-watchdog.log" "$LOG_DIR/ollama-watchdog-error.log"; do
    if [[ -r "$f" ]]; then
      echo "===== $f ====="
      tail -n 30 "$f"
    elif [[ -f "$f" ]]; then
      echo "===== $f ====="
      echo "Not readable by this user (run watchdog as root)."
    fi
  done
}

wait_for_ollama_api(){
  local seconds=$1 i
  for ((i=1; i<=seconds; i++)); do
    if ollama_api_ready; then
      return 0
    fi
    sleep 1
  done
  return 1
}

# Runs one short, identical generation request and prints a TSV line:
# total_ms, load_ms, uncached-prompt tok/s, generation tok/s, generated
# tokens, prompt tokens, cached prompt tokens (-1 when Ollama does not
# report them), response snippet. Since Ollama 0.33.3, prompt_eval_duration
# only times the prompt tokens that were NOT read from the prompt cache,
# while prompt_eval_count counts every prompt token; dividing the two
# directly inflates the prompt speed on repeated prompts, so the cached
# share is subtracted first when Ollama reports it. think_mode is "off"
# (think:false) or "default" (no think field, so thinking models may
# spend tokens thinking).
bench_run(){
  local model=$1 think_mode=$2 payload response raw total_ns load_ns p_count p_ns e_count e_ns p_cached content
  if [[ "$think_mode" == "off" ]]; then
    payload=$(jq -cn --arg model "$model" --argjson nctx "$OLLAMA_CONTEXT_LENGTH" \
      '{model:$model, messages:[{role:"user", content:"Réponds en une phrase courte : pourquoi le ciel est bleu ?"}], stream:false, think:false, options:{num_ctx:$nctx, num_predict:48, temperature:0}}') || return 1
  else
    payload=$(jq -cn --arg model "$model" --argjson nctx "$OLLAMA_CONTEXT_LENGTH" \
      '{model:$model, messages:[{role:"user", content:"Réponds en une phrase courte : pourquoi le ciel est bleu ?"}], stream:false, options:{num_ctx:$nctx, num_predict:48, temperature:0}}') || return 1
  fi
  response=$(curl -fsS --max-time 300 http://127.0.0.1:11434/api/chat \
    -H 'Content-Type: application/json' -d "$payload" 2>/dev/null) || return 1
  raw=$(printf '%s' "$response" | jq -r '[ (.total_duration // 0), (.load_duration // 0), (.prompt_eval_count // 0), (.prompt_eval_duration // 0), (.eval_count // 0), (.eval_duration // 0), (.prompt_eval_cached_count // -1) ] | @tsv' 2>/dev/null) || return 1
  IFS=$'\t' read -r total_ns load_ns p_count p_ns e_count e_ns p_cached <<< "$raw"
  content=$(printf '%s' "$response" | jq -r '.message.content // .response // ""' 2>/dev/null | tr '\n\t' '  ' | tr -d '\134' | cut -c1-90 || true)
  awk -v t="$total_ns" -v l="$load_ns" -v pc="$p_count" -v pd="$p_ns" -v ec="$e_count" -v ed="$e_ns" -v cached="$p_cached" -v c="$content" \
    'BEGIN { uncached = pc; if (cached >= 0) { uncached = pc - cached; if (uncached < 0) uncached = 0 } printf "%d\t%d\t%.1f\t%.1f\t%d\t%d\t%d\t%s", t / 1000000, l / 1000000, (pd > 0 ? uncached / (pd / 1000000000) : 0), (ed > 0 ? ec / (ed / 1000000000) : 0), ec, pc, cached, c }'
}

bench_print_line(){
  local label=$1 res=$2 total_ms load_ms p_tps e_tps e_count p_count p_cached content total_s load_s
  IFS=$'\t' read -r total_ms load_ms p_tps e_tps e_count p_count p_cached content <<< "$res"
  total_s=$(awk -v ms="${total_ms:-0}" 'BEGIN { printf "%.1f", ms / 1000 }')
  load_s=$(awk -v ms="${load_ms:-0}" 'BEGIN { printf "%.1f", ms / 1000 }')
  if [[ "${p_cached:-"-1"}" =~ ^[0-9]+$ ]]; then
    printf '%s : total %s s · chargement %s s · prompt non caché %s tok/s (%s tokens, dont %s en cache) · génération %s tok/s (%s tokens générés)\n' \
      "$label" "$total_s" "$load_s" "${p_tps:-0}" "${p_count:-0}" "$p_cached" "${e_tps:-0}" "${e_count:-0}"
  else
    printf '%s : total %s s · chargement %s s · prompt %s tok/s · génération %s tok/s (%s tokens générés)\n' \
      "$label" "$total_s" "$load_s" "${p_tps:-0}" "${e_tps:-0}" "${e_count:-0}"
  fi
  if [[ -n "${content:-}" ]]; then
    printf '   Réponse : %s\n' "$content"
  fi
}

# Prints installed model names with the saved default moved to the end, so
# a global benchmark finishes on the model the user normally uses.
ordered_present_model_names(){
  local names=$1 default_model=$2 name default_norm
  default_norm=$(normalize_model_name "$default_model")
  while IFS= read -r name; do
    [[ -n "$name" ]] || continue
    [[ "$(normalize_model_name "$name")" == "$default_norm" ]] || printf '%s\n' "$name"
  done <<< "$names"
  while IFS= read -r name; do
    [[ -n "$name" ]] || continue
    [[ "$(normalize_model_name "$name")" == "$default_norm" ]] && printf '%s\n' "$name"
  done <<< "$names"
  return 0
}

# Populated by bench_one_model for bench_summary_for_last.
LAST_BENCH_DEFAULT_RES=""
LAST_BENCH_OFF_RES=""
LAST_BENCH_HAVE_DEFAULT=0
LAST_BENCH_HAVE_OFF=0

bench_one_model(){
  local model=$1 res_default="" res_off="" have_default=0 have_off=0 d_total o_total gain
  LAST_BENCH_DEFAULT_RES=""
  LAST_BENCH_OFF_RES=""
  LAST_BENCH_HAVE_DEFAULT=0
  LAST_BENCH_HAVE_OFF=0

  info "Run 1/2 : thinking par défaut (sans think:false)..."
  if res_default=$(bench_run "$model" default); then
    have_default=1
    bench_print_line "Thinking par défaut" "$res_default"
  else
    err "Le run avec thinking par défaut a échoué pour le modèle : $model"
  fi
  echo
  info "Run 2/2 : think:false..."
  if res_off=$(bench_run "$model" off); then
    have_off=1
    bench_print_line "think:false        " "$res_off"
  else
    warn "think:false a été refusé par ce modèle (modèle sans mode réflexion, probablement) : ignore ce réglage pour lui."
  fi

  LAST_BENCH_DEFAULT_RES="$res_default"
  LAST_BENCH_OFF_RES="$res_off"
  LAST_BENCH_HAVE_DEFAULT="$have_default"
  LAST_BENCH_HAVE_OFF="$have_off"
  [[ "$have_default" -eq 1 || "$have_off" -eq 1 ]] || return 1

  if [[ "$have_default" -eq 1 && "$have_off" -eq 1 ]]; then
    d_total=$(printf '%s' "$res_default" | cut -f1)
    o_total=$(printf '%s' "$res_off" | cut -f1)
    if [[ "$o_total" =~ ^[0-9]+$ && "$d_total" =~ ^[0-9]+$ && "$d_total" -gt 0 && "$o_total" -lt "$d_total" ]]; then
      gain=$(awk -v d="$d_total" -v o="$o_total" 'BEGIN { printf "%.0f", (d - o) / d * 100 }')
      ok "Verdict mesuré pour $model : think:false a été environ ${gain}% plus rapide sur ce test."
    elif [[ "$o_total" =~ ^[0-9]+$ && "$d_total" =~ ^[0-9]+$ && "$o_total" -gt "$d_total" ]]; then
      warn "Verdict mesuré pour $model : think:false n'a pas été plus rapide sur ce test (le premier run inclut parfois le chargement ; relance le bench pour confirmer)."
    else
      info "Verdict mesuré pour $model : pas de différence nette entre les deux runs sur ce test."
    fi
  elif [[ "$have_off" -eq 1 ]]; then
    warn "Verdict pour $model : seul le run think:false a réussi ; compare avec prudence."
  else
    warn "Verdict pour $model : think:false indisponible/refusé ; utilise le comportement par défaut de ce modèle."
  fi
  return 0
}

bench_summary_for_last(){
  local model=$1 d_tps="-" o_tps="-" d_total o_total conclusion
  if [[ "$LAST_BENCH_HAVE_DEFAULT" -eq 1 ]]; then
    d_tps=$(printf '%s' "$LAST_BENCH_DEFAULT_RES" | cut -f4)
  fi
  if [[ "$LAST_BENCH_HAVE_OFF" -eq 1 ]]; then
    o_tps=$(printf '%s' "$LAST_BENCH_OFF_RES" | cut -f4)
  fi
  if [[ "$LAST_BENCH_HAVE_DEFAULT" -eq 1 && "$LAST_BENCH_HAVE_OFF" -eq 1 ]]; then
    d_total=$(printf '%s' "$LAST_BENCH_DEFAULT_RES" | cut -f1)
    o_total=$(printf '%s' "$LAST_BENCH_OFF_RES" | cut -f1)
    if [[ "$o_total" =~ ^[0-9]+$ && "$d_total" =~ ^[0-9]+$ && "$o_total" -lt "$d_total" ]]; then
      conclusion="think:false plus rapide sur ce test"
    elif [[ "$o_total" =~ ^[0-9]+$ && "$d_total" =~ ^[0-9]+$ && "$o_total" -gt "$d_total" ]]; then
      conclusion="pas de gain think:false mesuré"
    else
      conclusion="pas de différence nette"
    fi
  elif [[ "$LAST_BENCH_HAVE_OFF" -eq 1 ]]; then
    conclusion="seul think:false a répondu"
  elif [[ "$LAST_BENCH_HAVE_DEFAULT" -eq 1 ]]; then
    conclusion="think:false refusé/non applicable"
  else
    conclusion="ÉCHEC des deux runs"
  fi
  printf '%s | génération défaut %s tok/s | génération think:false %s tok/s | %s' "$model" "$d_tps" "$o_tps" "$conclusion"
}

run_bench(){
  local requested=${1:-} installed loaded mem_kb base public_url threads saved_default example_model
  local -a present_models=() models_to_bench=() summary_lines=()
  local model ordered successes=0 failures=0 global=0 idx
  require_commands curl jq
  ollama_api_ready || die "Ollama API is not answering, so the benchmark cannot run. Try: ola recover"
  installed=$(installed_model_names) || die "Could not read the installed model list from Ollama."
  [[ -n "$installed" ]] || die "No model is currently downloaded on disk. Install one first with: ola use <model>"
  saved_default=$(saved_model_name)
  ordered=$(ordered_present_model_names "$installed" "$saved_default")
  while IFS= read -r model; do
    [[ -n "$model" ]] || continue
    present_models+=("$model")
  done <<< "$ordered"

  if [[ -n "$requested" && "$requested" != "all" && "$requested" != "--all" ]]; then
    is_valid_model_name "$requested" || die "Invalid model name: $requested (example: qwen3:1.7b)"
    model_names_contain "$installed" "$requested" \
      || die "Model is not downloaded on disk: $requested. Install and load it first with: ola use $requested"
    models_to_bench=("$requested")
    example_model="$requested"
  else
    global=1
    models_to_bench=("${present_models[@]}")
    example_model="${models_to_bench[$((${#models_to_bench[@]} - 1))]}"
    if model_names_contain "$installed" "$saved_default"; then
      example_model="$saved_default"
    fi
  fi
  threads=$(cpu_physical_cores)

  echo "--- Ola bench ---"
  if [[ "$global" -eq 1 ]]; then
    info "Portée globale : ${#models_to_bench[@]} modèle(s) présent(s) sur le disque, testés un par un."
    info "Modèles pris en compte : $(printf '%s' "$installed" | tr '\n' ' ')"
    info "Le modèle par défaut est testé en dernier afin de terminer avec lui : $example_model"
  else
    info "Portée ciblée : un seul modèle."
  fi
  info "CPU : $(cpu_logical_cores) logique(s), environ $threads physique(s) — $(cpu_speed_summary)"
  mem_kb=$(awk '/^MemAvailable:/ { print $2 }' /proc/meminfo 2>/dev/null || true)
  if [[ "$mem_kb" =~ ^[0-9]+$ ]]; then
    info "RAM disponible : environ $((mem_kb / 1024)) MB"
  fi
  echo "Chaque modèle est testé séparément ; les autres modèles chargés sont déchargés de la RAM avant son test. Aucun fichier de modèle n'est modifié ni supprimé."
  echo "Test identique pour les deux runs de chaque modèle : même question courte, 48 tokens max, num_ctx $OLLAMA_CONTEXT_LENGTH, température 0."

  for idx in "${!models_to_bench[@]}"; do
    model="${models_to_bench[$idx]}"
    echo
    echo "=== Modèle $((idx + 1))/${#models_to_bench[@]} : $model ==="
    stop_loaded_models_except_soft "$model"
    loaded=$(loaded_model_names 2>/dev/null || true)
    if model_names_contain "$loaded" "$model"; then
      info "Le modèle est déjà chargé en RAM."
    else
      info "Le modèle n'est pas encore chargé : le premier run inclura son temps de chargement."
    fi
    if bench_one_model "$model"; then
      successes=$((successes + 1))
    else
      failures=$((failures + 1))
    fi
    summary_lines+=("$(bench_summary_for_last "$model")")
  done

  if [[ "$global" -eq 1 ]]; then
    echo
    echo "--- Synthèse globale ---"
    printf '%s\n' "${summary_lines[@]}"
  fi
  if [[ "$successes" -eq 0 ]]; then
    die "Benchmark failed for every tested model. Check: ola logs"
  fi
  if [[ "$failures" -gt 0 ]]; then
    warn "Benchmark terminé avec $failures échec(s) et $successes succès. Les modèles en échec sont signalés dans la synthèse."
  fi

  base="http://127.0.0.1:11434"
  if [[ -r "$URL_FILE" ]]; then
    public_url=$(head -n 1 "$URL_FILE" 2>/dev/null || true)
    [[ -n "$public_url" ]] && base="$public_url"
  fi
  cat <<EOF

Conseils vitesse, du plus efficace au plus fin :
  1. Questions simples : envoie "think": false (mesuré ci-dessus, modèle par modèle) et limite la longueur avec options.num_predict (ex. 128 ou 256). Si un modèle refuse "think": false, ignore ce réglage pour ce modèle précis.
  2. Utilise "stream": true dans tes applis : la génération n'est pas plus rapide, mais les tokens s'affichent au fur et à mesure.
  3. Côté client, essaie options.num_thread ≈ $threads (cœurs physiques estimés) et compare ; options.num_batch ne sert surtout qu'aux très longs prompts.
  4. Garde un seul modèle chargé (ola ps / ola unload) : sur un petit sandbox, la RAM libre évite les lenteurs.
  5. Le keep-alive serveur actuel ($(saved_keep_alive)) garde le modèle en RAM après chaque requête : réponses suivantes plus rapides, mais RAM occupée. ola fluid warm garde un modèle chaud 30 minutes pour une session ; ola unload libère tout de suite. Fluidité mesurée (1er token, local et public) : ola bench --stream ; preset stable à copier dans ton client : ola fluid preset.

Exemple rapide à copier (modèle utilisé dans l'exemple : $example_model ; remplace l'URL par la tienne si besoin) :
curl -fsS $base/api/chat -H 'Content-Type: application/json' -d '{
  "model": "$example_model",
  "messages": [{"role": "user", "content": "Dis bonjour en une phrase."}],
  "stream": true,
  "think": false,
  "options": {"num_predict": 128, "num_thread": $threads}
}'
EOF
  [[ "$failures" -eq 0 ]]
}

# --- Pack Fluidité ---------------------------------------------------------
# Total generation speed (tok/s) is not what a user feels first. What is
# felt is: how long until the first visible token (time to first token,
# TTFT), and whether the streamed tokens then arrive regularly or in
# bursts. Ollama streams newline-delimited JSON chunks by default and puts
# the usage metrics in the final chunk. The helpers below measure TTFT and
# chunk gaps against the local API and, when a public URL is saved,
# through the tunnel too: Cloudflare documents that proxied responses are
# buffered unless the origin answers with Content-Type: text/event-stream,
# while Ollama streams NDJSON — so the public path is measured, not
# assumed to stream smoothly.

# Prints one streaming measurement as a TSV line: total_ms (wall clock),
# load_ms, time-to-first-visible-token ms, uncached-prompt tok/s,
# generation tok/s, generated tokens, prompt tokens, cached prompt tokens
# (-1 when unreported), largest gap ms between visible chunks, visible
# chunk count, response snippet. The request uses the fluid preset (fixed
# num_ctx/num_thread, 48 tokens max) and leaves the model warm for
# FLUID_WARM_KEEP_ALIVE so the next real request starts hot.
stream_bench_run(){
  local model=$1 base=$2 think_mode=$3 payload tmp_dir start_ns end_ns line content done_flag
  local -a pipe_status=()
  local times_file snippet_file final_file metrics _total_ns load_ns p_count p_ns e_count e_ns p_cached
  local first_ns gap_stats max_gap_ms chunk_count snippet
  tmp_dir=$(mktemp -d) || return 1
  times_file="$tmp_dir/times"; snippet_file="$tmp_dir/snippet"; final_file="$tmp_dir/final"
  : > "$times_file"; : > "$snippet_file"
  if [[ "$think_mode" == "off" ]]; then
    payload=$(jq -cn --arg model "$model" --argjson nctx "$OLLAMA_CONTEXT_LENGTH" --argjson threads "$(cpu_physical_cores)" --arg warm "$FLUID_WARM_KEEP_ALIVE" \
      '{model:$model, messages:[{role:"user", content:"Réponds en une phrase courte : pourquoi le ciel est bleu ?"}], stream:true, think:false, keep_alive:$warm, options:{num_ctx:$nctx, num_predict:48, temperature:0, num_thread:$threads}}') || { rm -rf "$tmp_dir"; return 1; }
  else
    payload=$(jq -cn --arg model "$model" --argjson nctx "$OLLAMA_CONTEXT_LENGTH" --argjson threads "$(cpu_physical_cores)" --arg warm "$FLUID_WARM_KEEP_ALIVE" \
      '{model:$model, messages:[{role:"user", content:"Réponds en une phrase courte : pourquoi le ciel est bleu ?"}], stream:true, keep_alive:$warm, options:{num_ctx:$nctx, num_predict:48, temperature:0, num_thread:$threads}}') || { rm -rf "$tmp_dir"; return 1; }
  fi
  start_ns=$(date +%s%N)
  curl -fsS -N --max-time 300 "${base}/api/chat" \
    -H 'Content-Type: application/json' -d "$payload" 2>/dev/null \
    | while IFS= read -r line; do
        content=$(printf '%s' "$line" | jq -r '.message.content // .response // ""' 2>/dev/null || true)
        if [[ -n "$content" ]]; then
          date +%s%N >> "$times_file"
          printf '%s' "$content" >> "$snippet_file"
        fi
        done_flag=$(printf '%s' "$line" | jq -r '.done // false' 2>/dev/null || true)
        if [[ "$done_flag" == "true" ]]; then
          printf '%s' "$line" > "$final_file"
        fi
      done
  pipe_status=("${PIPESTATUS[@]}")
  end_ns=$(date +%s%N)
  if [[ "${pipe_status[0]:-1}" -ne 0 || ! -s "$final_file" ]]; then
    rm -rf "$tmp_dir"
    return 1
  fi
  metrics=$(jq -r '[ (.total_duration // 0), (.load_duration // 0), (.prompt_eval_count // 0), (.prompt_eval_duration // 0), (.eval_count // 0), (.eval_duration // 0), (.prompt_eval_cached_count // -1) ] | @tsv' "$final_file" 2>/dev/null) || { rm -rf "$tmp_dir"; return 1; }
  IFS=$'\t' read -r _total_ns load_ns p_count p_ns e_count e_ns p_cached <<< "$metrics"
  first_ns=$(head -n 1 "$times_file" 2>/dev/null || true)
  gap_stats=$(awk 'NR == 1 { prev = $1 } NR > 1 { gap = $1 - prev; if (gap > max) max = gap; prev = $1 } END { printf "%d %d", max / 1000000, NR }' "$times_file")
  max_gap_ms=${gap_stats%% *}; chunk_count=${gap_stats##* }
  snippet=$(tr '\n\t' '  ' < "$snippet_file" | tr -d '\134' | cut -c1-90 || true)
  awk -v start="$start_ns" -v end="$end_ns" -v first="${first_ns:-0}" -v load="$load_ns" -v pc="$p_count" -v pd="$p_ns" -v ec="$e_count" -v ed="$e_ns" -v cached="$p_cached" -v gap="${max_gap_ms:-0}" -v chunks="${chunk_count:-0}" -v c="$snippet" \
    'BEGIN { uncached = pc; if (cached >= 0) { uncached = pc - cached; if (uncached < 0) uncached = 0 } ttft = (first > 0 ? (first - start) / 1000000 : (end - start) / 1000000); printf "%d\t%d\t%d\t%.1f\t%.1f\t%d\t%d\t%d\t%d\t%d\t%s", (end - start) / 1000000, load / 1000000, ttft, (pd > 0 ? uncached / (pd / 1000000000) : 0), (ed > 0 ? ec / (ed / 1000000000) : 0), ec, pc, cached, gap, chunks, c }'
  rm -rf "$tmp_dir"
}

# Populated by stream_bench_one_model.
LAST_STREAM_RES=""
LAST_STREAM_MODE=""

# Tries think:false first (fastest visible answer), then the model's
# default behaviour for models that refuse think:false.
stream_bench_one_model(){
  local model=$1 base=$2 res
  LAST_STREAM_RES=""; LAST_STREAM_MODE=""
  if res=$(stream_bench_run "$model" "$base" off); then
    LAST_STREAM_MODE="think:false"
  elif res=$(stream_bench_run "$model" "$base" default); then
    LAST_STREAM_MODE="thinking par défaut"
  else
    return 1
  fi
  LAST_STREAM_RES="$res"
  return 0
}

fmt_ms_s(){
  awk -v ms="${1:-0}" 'BEGIN { if (ms !~ /^[0-9]+$/) ms = 0; printf "%.1f", ms / 1000 }'
}

stream_print_line(){
  local label=$1 res=$2 total_ms load_ms ttft_ms p_tps e_tps _e_count _p_count _p_cached max_gap_ms chunk_count content
  IFS=$'\t' read -r total_ms load_ms ttft_ms p_tps e_tps _e_count _p_count _p_cached max_gap_ms chunk_count content <<< "$res"
  printf '%s : 1er token visible %s s · total %s s · chargement %s s · génération %s tok/s · prompt non caché %s tok/s · plus grand trou %s s · %s morceaux visibles\n' \
    "$label" "$(fmt_ms_s "${ttft_ms:-0}")" "$(fmt_ms_s "${total_ms:-0}")" "$(fmt_ms_s "${load_ms:-0}")" "${e_tps:-0}" "${p_tps:-0}" "$(fmt_ms_s "${max_gap_ms:-0}")" "${chunk_count:-0}"
  if [[ -n "${content:-}" ]]; then
    printf '   Réponse : %s\n' "$content"
  fi
}

run_stream_bench(){
  local requested=${1:-} installed loaded saved_default ordered public_base=""
  local -a present_models=() models_to_bench=() summary_lines=()
  local model idx global=0 successes=0 failures=0 public_failures=0
  local local_ttft local_load public_ttft public_gap conclusion
  require_commands curl jq
  ollama_api_ready || die "Ollama API is not answering, so the streaming benchmark cannot run. Try: ola recover"
  installed=$(installed_model_names) || die "Could not read the installed model list from Ollama."
  [[ -n "$installed" ]] || die "No model is currently downloaded on disk. Install one first with: ola use <model>"
  saved_default=$(saved_model_name)
  ordered=$(ordered_present_model_names "$installed" "$saved_default")
  while IFS= read -r model; do
    [[ -n "$model" ]] || continue
    present_models+=("$model")
  done <<< "$ordered"

  if [[ -n "$requested" && "$requested" != "all" && "$requested" != "--all" ]]; then
    is_valid_model_name "$requested" || die "Invalid model name: $requested (example: qwen3:1.7b)"
    model_names_contain "$installed" "$requested" \
      || die "Model is not downloaded on disk: $requested. Install and load it first with: ola use $requested"
    models_to_bench=("$requested")
  else
    global=1
    models_to_bench=("${present_models[@]}")
  fi

  if [[ -r "$URL_FILE" ]]; then
    public_base=$(head -n 1 "$URL_FILE" 2>/dev/null || true)
  fi
  if [[ -n "$public_base" ]]; then
    if curl -fsS --max-time 10 "${public_base}/api/version" >/dev/null 2>&1; then
      info "URL publique enregistrée joignable : le streaming sera aussi mesuré à travers le tunnel ($public_base)."
    else
      warn "URL publique enregistrée non joignable depuis ce sandbox ($public_base) : mesure publique ignorée. Le DNS local du sandbox peut échouer alors que le tunnel fonctionne depuis l'extérieur ; vérifie aussi depuis ton navigateur/client."
      public_base=""
    fi
  else
    info "Aucune URL publique enregistrée lisible : mesure locale uniquement."
  fi

  echo "--- Ola bench streaming (fluidité) ---"
  if [[ "$global" -eq 1 ]]; then
    info "Portée globale : ${#models_to_bench[@]} modèle(s) présent(s) sur le disque, testés un par un, modèle par défaut en dernier."
  else
    info "Portée ciblée : un seul modèle."
  fi
  echo "Question courte identique, 48 tokens max, num_ctx $OLLAMA_CONTEXT_LENGTH, température 0, num_thread $(cpu_physical_cores), keep_alive $FLUID_WARM_KEEP_ALIVE (le modèle testé reste chaud ensuite)."
  echo "Le TTFT mesure le délai avant le premier morceau de réponse VISIBLE (le contenu 'thinking' caché ne compte pas)."

  for idx in "${!models_to_bench[@]}"; do
    model="${models_to_bench[$idx]}"
    echo
    echo "=== Modèle $((idx + 1))/${#models_to_bench[@]} : $model ==="
    stop_loaded_models_except_soft "$model"
    loaded=$(loaded_model_names 2>/dev/null || true)
    if model_names_contain "$loaded" "$model"; then
      info "Le modèle est déjà chargé en RAM."
    else
      info "Le modèle n'est pas encore chargé : le premier run inclura son temps de chargement."
    fi

    local_ttft=""; local_load=""; conclusion=""
    if stream_bench_one_model "$model" "http://127.0.0.1:11434"; then
      successes=$((successes + 1))
      stream_print_line "Local  ($LAST_STREAM_MODE)" "$LAST_STREAM_RES"
      local_ttft=$(printf '%s' "$LAST_STREAM_RES" | cut -f3)
      local_load=$(printf '%s' "$LAST_STREAM_RES" | cut -f2)
    else
      failures=$((failures + 1))
      err "Le streaming local a échoué pour le modèle : $model"
      summary_lines+=("$model | ÉCHEC du streaming local")
      continue
    fi

    if [[ -n "$public_base" ]]; then
      if stream_bench_one_model "$model" "$public_base"; then
        stream_print_line "Public ($LAST_STREAM_MODE)" "$LAST_STREAM_RES"
        public_ttft=$(printf '%s' "$LAST_STREAM_RES" | cut -f3)
        public_gap=$(printf '%s' "$LAST_STREAM_RES" | cut -f9)
        if [[ "$public_ttft" =~ ^[0-9]+$ && "$local_ttft" =~ ^[0-9]+$ ]] \
          && awk -v p="$public_ttft" -v l="$local_ttft" 'BEGIN { exit !(p > l * 1.5 && (p - l) > 500) }'; then
          conclusion="chemin public beaucoup plus lent à démarrer que le local : buffering du tunnel ou du client possible (mesuré, pas supposé)"
        elif [[ "$public_gap" =~ ^[0-9]+$ && "$public_gap" -gt 1000 ]]; then
          conclusion="flux public irrégulier sur ce test (trous > 1 s entre morceaux visibles)"
        else
          conclusion="démarrage local/public cohérents sur ce test"
        fi
        summary_lines+=("$model | TTFT local $(fmt_ms_s "$local_ttft") s | TTFT public $(fmt_ms_s "$public_ttft") s | $conclusion")
      else
        public_failures=$((public_failures + 1))
        warn "Le streaming public a échoué pour $model (le local fonctionne) : tunnel/client public à vérifier, voir ola doctor."
        summary_lines+=("$model | TTFT local $(fmt_ms_s "$local_ttft") s | streaming public EN ÉCHEC | vérifier le tunnel et le client public")
      fi
    else
      if [[ "$local_load" =~ ^[0-9]+$ && "$local_load" -ge 2000 ]]; then
        conclusion="premier token dominé par le chargement du modèle : garde-le chaud (ola fluid warm)"
      else
        conclusion="fluide sur ce test local"
      fi
      summary_lines+=("$model | TTFT local $(fmt_ms_s "$local_ttft") s | $conclusion")
    fi
  done

  if [[ "$global" -eq 1 || -n "$public_base" ]]; then
    echo
    echo "--- Synthèse fluidité ---"
    printf '%s\n' "${summary_lines[@]}"
  fi
  if [[ "$successes" -eq 0 ]]; then
    die "Streaming benchmark failed for every tested model. Check: ola logs"
  fi
  if [[ "$failures" -gt 0 ]]; then
    warn "Benchmark streaming terminé avec $failures échec(s) local/locaux et $successes succès."
  fi
  if [[ "$public_failures" -gt 0 ]]; then
    warn "$public_failures mesure(s) publique(s) en échec : cela vise le chemin tunnel/client, pas le modèle."
  fi
  cat <<EOF

Comment rendre les réponses plus fluides au quotidien :
  1. Garde UN seul modèle chaud pendant une session : ola fluid warm [modèle] (keep-alive $FLUID_WARM_KEEP_ALIVE), et libère la RAM ensuite avec ola unload.
  2. Envoie toujours le même preset stable à ce modèle (ola fluid preset [modèle]) : stream:true, think:false si le modèle l'accepte, même num_ctx à chaque requête — changer num_ctx ou certains réglages du runner entre deux requêtes peut forcer un rechargement du modèle.
  3. Garde un préfixe de prompt stable (même system prompt, historique dans le même ordre) : Ollama réutilise le cache du prompt pour la partie inchangée ; les compteurs "prompt non caché" ci-dessus le montrent.
  4. Limite num_predict au besoin réel et évite de changer de modèle au milieu d'une session.
  5. Si le TTFT public est très supérieur au TTFT local, le souci est le chemin public (tunnel/client), pas le modèle : compare toujours les deux lignes avant de changer de réglage serveur.
EOF
  [[ "$failures" -eq 0 ]]
}

fluid_keep_alive_for_requests(){
  if [[ "$(saved_keep_alive)" != "5m" ]]; then
    printf '%s' "$(saved_keep_alive)"
  else
    printf '%s' "$FLUID_WARM_KEEP_ALIVE"
  fi
}

show_fluid_status(){
  local keepalive_cfg mem_kb swap_kb ps_json ps_lines installed saved_default loaded_count public_url
  local m_name m_size m_expires m_ctx
  select_supervisor_paths
  echo "--- Ola fluidité ---"
  echo "Mode Pack Speed : $(saved_speed_mode) (détails : ola speed)"
  if [[ -f "$KEEPALIVE_FILE" && ! -r "$KEEPALIVE_FILE" ]]; then
    echo "Keep-alive serveur enregistré : non lisible sans root (fichier $KEEPALIVE_FILE)"
  else
    echo "Keep-alive serveur enregistré : $(saved_keep_alive) (fichier $KEEPALIVE_FILE)"
  fi
  if [[ -r "$SUP_DIR/ollama.conf" ]]; then
    keepalive_cfg=$(ollama_config_value OLLAMA_KEEP_ALIVE)
    echo "Keep-alive effectif (Supervisor) : ${keepalive_cfg:-inconnu}"
  else
    echo "Keep-alive effectif : non lisible par cet utilisateur (relance en root pour le détail)."
  fi
  echo "Keep-alive utilisé par 'ola fluid warm' et le bench streaming : $(fluid_keep_alive_for_requests) après chaque requête."
  mem_kb=$(awk '/^MemAvailable:/ { print $2 }' /proc/meminfo 2>/dev/null || true)
  if [[ "$mem_kb" =~ ^[0-9]+$ ]]; then
    echo "RAM disponible : environ $((mem_kb / 1024)) MB"
  fi
  swap_kb=$(awk '/^SwapFree:/ { print $2 }' /proc/meminfo 2>/dev/null || true)
  if [[ "$swap_kb" =~ ^[0-9]+$ ]]; then
    echo "Swap libre : environ $((swap_kb / 1024)) MB (si le swap se remplit pendant une réponse, le sandbox échange : réponses par à-coups)"
  fi
  if command -v curl >/dev/null 2>&1 && command -v jq >/dev/null 2>&1 && ollama_api_ready; then
    saved_default=$(saved_model_name)
    installed=$(installed_model_names 2>/dev/null || true)
    if [[ -n "$installed" ]]; then
      echo "Modèles présents sur le disque : $(printf '%s' "$installed" | tr '\n' ' ')(défaut : $saved_default)"
    fi
    ps_json=$(curl -fsS --max-time 10 http://127.0.0.1:11434/api/ps 2>/dev/null || true)
    ps_lines=$(printf '%s' "$ps_json" | jq -r '.models[]? | [(.name // ""), ((.size // 0) | tostring), (.expires_at // ""), ((.context_length // "") | tostring)] | @tsv' 2>/dev/null || true)
    loaded_count=0
    if [[ -n "$ps_lines" ]]; then
      echo "Modèle(s) actuellement en RAM :"
      while IFS=$'\t' read -r m_name m_size m_expires m_ctx; do
        [[ -n "$m_name" ]] || continue
        loaded_count=$((loaded_count + 1))
        echo "  - $m_name · occupe environ $(format_model_size "${m_size:-0}") · expiration keep-alive : ${m_expires:-inconnue}${m_ctx:+ · contexte chargé : $m_ctx}"
      done <<< "$ps_lines"
    fi
    if [[ "$loaded_count" -eq 0 ]]; then
      echo "Aucun modèle chargé en RAM : la prochaine requête paiera le temps de chargement (visible dans le TTFT)."
    fi
  else
    echo "API Ollama locale non joignable : état des modèles en RAM inconnu."
  fi
  public_url=""
  if [[ -r "$URL_FILE" ]]; then
    public_url=$(head -n 1 "$URL_FILE" 2>/dev/null || true)
  fi
  if [[ -n "$public_url" ]]; then
    echo "URL publique enregistrée : $public_url (compare son TTFT au local avec : ola bench --stream)"
  fi
  cat <<'EOF'

Actions fluidité :
  ola fluid warm [modèle]        charge un seul modèle et le garde chaud pour la session
  ola fluid preset [modèle]      affiche un preset de requête stable et rapide à copier dans ton client
  ola bench --stream [modèle]    mesure le temps avant le 1er token visible et la régularité du flux, en local et via l'URL publique
  ola fluid keepalive <durée>    change le keep-alive par défaut du serveur (ex. 30m, 1h, -1 = toujours chargé ; reset = retour à 5m), root, avec retour arrière auto
Le keep-alive ne rend pas la génération plus rapide : il supprime seulement le rechargement du modèle entre deux requêtes.
Un seul modèle chargé à la fois reste la règle sur un petit sandbox (voir ola speed).
EOF
}

warm_model_command(){
  local target=${1:-} model installed loaded payload keep_alive_value
  require_commands curl jq
  ollama_api_ready || die "Ollama API is not answering. Try: ola recover"
  installed=$(installed_model_names) || die "Could not read the installed model list from Ollama."
  [[ -n "$installed" ]] || die "No model is currently downloaded on disk. Install one first with: ola use <model>"
  model="$target"
  if [[ -z "$model" ]]; then
    model=$(saved_model_name)
  fi
  is_valid_model_name "$model" || die "Invalid model name: $model"
  model_names_contain "$installed" "$model" \
    || die "Model is not downloaded on disk: $model. Install and load it first with: ola use $model"
  keep_alive_value=$(fluid_keep_alive_for_requests)
  info "Préchauffage de $model : il restera chargé en RAM environ $keep_alive_value après cette requête."
  stop_loaded_models_except "$model"
  payload=$(jq -cn --arg model "$model" --argjson nctx "$OLLAMA_CONTEXT_LENGTH" --argjson threads "$(cpu_physical_cores)" --arg keepalive "$keep_alive_value" \
    '{model:$model, messages:[{role:"user", content:"Reply only with OK."}], stream:false, keep_alive:$keepalive, options:{num_ctx:$nctx, num_predict:8, temperature:0, num_thread:$threads}}') || die "Could not build the warm-up request."
  curl -fsS --max-time 300 http://127.0.0.1:11434/api/chat \
    -H 'Content-Type: application/json' -d "$payload" >/dev/null 2>&1 \
    || die "The warm-up request failed for: $model. Check: ola logs"
  loaded=$(loaded_model_names) || die "Could not read the loaded model list after warm-up."
  model_names_contain "$loaded" "$model" || die "Ollama did not keep the model loaded after warm-up: $model"
  ok "Modèle chaud et chargé en RAM : $model (keep-alive $keep_alive_value). Pendant ta session, envoie-lui toujours le même preset : ola fluid preset $model"
  info "Pour libérer la RAM après la session : ola unload"
}

fluid_preset(){
  local target=${1:-} model installed show_json capabilities param_size think_line threads keep_alive_value show_note=""
  require_commands curl jq
  ollama_api_ready || die "Ollama API is not answering. Try: ola recover"
  installed=$(installed_model_names) || die "Could not read the installed model list from Ollama."
  [[ -n "$installed" ]] || die "No model is currently downloaded on disk. Install one first with: ola use <model>"
  model="$target"
  if [[ -z "$model" ]]; then
    model=$(saved_model_name)
  fi
  is_valid_model_name "$model" || die "Invalid model name: $model"
  model_names_contain "$installed" "$model" \
    || die "Model is not downloaded on disk: $model. Install and load it first with: ola use $model"
  show_json=$(curl -fsS --max-time 15 http://127.0.0.1:11434/api/show \
    -H 'Content-Type: application/json' -d "$(jq -cn --arg model "$model" '{model:$model}')" 2>/dev/null || true)
  capabilities=""
  param_size=""
  think_line=""
  if [[ -n "$show_json" ]]; then
    capabilities=$(printf '%s' "$show_json" | jq -r '(.capabilities // []) | join(", ")' 2>/dev/null || true)
    param_size=$(printf '%s' "$show_json" | jq -r '.details.parameter_size // empty' 2>/dev/null || true)
    if printf '%s' "$show_json" | jq -e '(.capabilities // []) | index("thinking")' >/dev/null 2>&1; then
      think_line='  "think": false,'
    fi
  else
    show_note=" (informations /api/show indisponibles : preset générique)"
  fi
  threads=$(cpu_physical_cores)
  keep_alive_value=$(fluid_keep_alive_for_requests)
  echo "--- Preset fluidité pour $model ---"
  if [[ -n "$param_size" ]]; then
    echo "Taille des paramètres : $param_size"
  fi
  if [[ -n "$capabilities" ]]; then
    echo "Capacités déclarées par Ollama : $capabilities"
  fi
  cat <<EOF
Preset stable à réutiliser tel quel pour CHAQUE requête de ta session$show_note :
{
  "model": "$model",
  "stream": true,
  "keep_alive": "$keep_alive_value",
${think_line}  "messages": [{"role": "user", "content": "Ta question ici"}],
  "options": {"num_ctx": $OLLAMA_CONTEXT_LENGTH, "num_predict": 256, "num_thread": $threads, "temperature": 0}
}
Règles qui évitent les lenteurs invisibles :
  - même num_ctx, même num_thread et même structure de requête à chaque appel : changer ces réglages entre deux requêtes peut forcer Ollama à recharger le modèle ;
  - garde le même début de prompt (system prompt + historique dans le même ordre) : la partie inchangée est relue depuis le cache du prompt au lieu d'être réévaluée ;
  - "think": false seulement si la ligne est présente ci-dessus (modèle qui déclare la capacité thinking) ; sinon ne l'envoie pas ;
  - un seul modèle par session : changer de modèle recharge à chaque fois (voir ola fluid warm).
EOF
}

rollback_keepalive_config(){
  local backup=$1 prev_existed=$2 prev_value=$3
  cp -a "$backup" "$SUP_DIR/ollama.conf" 2>/dev/null || true
  chmod 600 "$SUP_DIR/ollama.conf" 2>/dev/null || true
  if [[ "$prev_existed" -eq 1 ]]; then
    printf '%s\n' "$prev_value" > "$KEEPALIVE_FILE" 2>/dev/null || true
    chmod 600 "$KEEPALIVE_FILE" 2>/dev/null || true
  else
    rm -f "$KEEPALIVE_FILE"
  fi
  supervisor_apply >/dev/null 2>&1 || true
  supervisor_ctl start ollama >/dev/null 2>&1 || true
  wait_for_supervisor_program ollama 30 >/dev/null 2>&1 || true
  wait_for_ollama_api 30 || true
}

apply_keep_alive(){
  local target=$1 ollama_bin current installed verify_model="" backup prev_existed=0 prev_value=""
  select_supervisor_paths
  [[ -f "$SUP_DIR/ollama.conf" ]] || die "Ollama Supervisor config not found: $SUP_DIR/ollama.conf. Run setup first: ola setup"
  ollama_bin=$(ollama_bin_path) || die "Ollama binary not found. Run setup first: ola setup"
  require_commands curl jq
  ensure_service_users
  current=$(saved_keep_alive)

  if ! supervisor_program_running ollama; then
    info "Ollama is not RUNNING; starting it before applying the keep-alive default..."
    supervisor_ctl start ollama 2>/dev/null || supervisor_ctl restart ollama \
      || die "Could not start Ollama. Check: ola logs"
    wait_for_supervisor_program ollama 30 || die "Ollama did not reach RUNNING. Check: ola logs"
  fi
  wait_for_ollama_api 30 || die "Ollama API is not answering. Try: ola recover"

  installed=$(installed_model_names 2>/dev/null || true)
  if [[ -n "$installed" ]]; then
    verify_model=$(saved_model_name)
    if ! model_names_contain "$installed" "$verify_model"; then
      verify_model=$(printf '%s' "$installed" | head -n 1)
    fi
  fi

  if [[ "$target" == "$current" ]] && [[ "$(ollama_config_value OLLAMA_KEEP_ALIVE)" == "$target" ]]; then
    info "Le keep-alive serveur est déjà à $target ; vérification globale quand même."
    if [[ -n "$verify_model" ]]; then
      verify_model_chat "$verify_model" || die "Verification chat failed for the present model: $verify_model"
      ok "Keep-alive déjà actif ($target) et modèle vérifié : $verify_model"
    else
      ok "Keep-alive déjà actif : $target (aucun modèle présent à vérifier)."
    fi
    return 0
  fi

  backup=$(mktemp) || die "Could not create a temporary backup file."
  cp -a "$SUP_DIR/ollama.conf" "$backup" || die "Could not back up the Ollama Supervisor config."
  if [[ -f "$KEEPALIVE_FILE" ]]; then
    prev_existed=1
    prev_value=$(head -n 1 "$KEEPALIVE_FILE" 2>/dev/null || true)
  fi

  if [[ -n "$verify_model" ]]; then
    info "Vérification avant changement sur le modèle présent : $verify_model"
    if ! verify_model_chat "$verify_model"; then
      warn "Le modèle $verify_model ne répond pas avant le changement ; le changement continue, mais un échec identique après ne déclenchera pas de retour arrière automatique."
      verify_model=""
    fi
  fi

  info "Application du keep-alive serveur par défaut : $target (mode Pack Speed conservé : $(saved_speed_mode))"
  save_keep_alive "$target"
  write_ollama_supervisor_config "$ollama_bin" "$(saved_speed_mode)"
  if ! supervisor_apply; then
    rollback_keepalive_config "$backup" "$prev_existed" "$prev_value"
    rm -f "$backup"
    die "Supervisor rejected the new config; the previous keep-alive default was restored."
  fi
  supervisor_ctl start ollama >/dev/null 2>&1 || true
  if ! wait_for_supervisor_program ollama 30 || ! wait_for_ollama_api 60; then
    rollback_keepalive_config "$backup" "$prev_existed" "$prev_value"
    rm -f "$backup"
    die "Ollama did not come back after the keep-alive change; the previous configuration was restored."
  fi
  if [[ -n "$verify_model" ]]; then
    if ! verify_model_chat "$verify_model"; then
      rollback_keepalive_config "$backup" "$prev_existed" "$prev_value"
      rm -f "$backup"
      die "Verification chat failed after the keep-alive change for: $verify_model. The previous configuration was restored."
    fi
    ok "Modèle vérifié après changement : $verify_model"
  else
    warn "Aucun modèle présent vérifié (aucun avant le changement non plus) ; pense à tester avec : ola doctor"
  fi
  rm -f "$backup"
  ok "Keep-alive serveur par défaut : $target (fichier $KEEPALIVE_FILE, configuration Supervisor régénérée)."
  echo "Effet réel : un modèle inactif reste chargé en RAM pendant $target après sa dernière requête. La première requête suivante démarre donc sans rechargement, mais la RAM du modèle reste occupée entre-temps."
  if [[ "$target" == "-1" ]]; then
    warn "keep-alive -1 : le modèle reste chargé jusqu'à ola unload, ola use <autre modèle> ou l'arrêt d'Ollama. À réserver à une session de travail, pas à un petit sandbox laissé allumé sans surveillance RAM."
  fi
  echo "Revenir en arrière : ola fluid keepalive reset (retour à 5m). État complet : ola fluid"
}

show_speed(){
  local mode flash kv mem_kb loaded installed saved_default model
  select_supervisor_paths
  mode=$(saved_speed_mode)
  echo "--- Ola speed (Pack Speed) ---"
  if [[ -f "$SPEED_FILE" && ! -r "$SPEED_FILE" ]]; then
    echo "Mode enregistré : non lisible sans root (fichier $SPEED_FILE)"
  else
    echo "Mode enregistré : $mode (fichier $SPEED_FILE)"
  fi
  echo "Configuration Supervisor effective ($SUP_DIR/ollama.conf) :"
  if [[ -r "$SUP_DIR/ollama.conf" ]]; then
    flash=$(ollama_config_value OLLAMA_FLASH_ATTENTION)
    kv=$(ollama_config_value OLLAMA_KV_CACHE_TYPE)
    echo "  OLLAMA_FLASH_ATTENTION : ${flash:-non défini (désactivé)}"
    echo "  OLLAMA_KV_CACHE_TYPE   : ${kv:-non défini (f16 par défaut)}"
    echo "  OLLAMA_CONTEXT_LENGTH  : $(ollama_config_value OLLAMA_CONTEXT_LENGTH)"
    echo "  OLLAMA_KEEP_ALIVE      : $(ollama_config_value OLLAMA_KEEP_ALIVE)"
    echo "  OLLAMA_MAX_LOADED_MODELS : $(ollama_config_value OLLAMA_MAX_LOADED_MODELS)"
    echo "  OLLAMA_NUM_PARALLEL    : $(ollama_config_value OLLAMA_NUM_PARALLEL)"
  else
    echo "  Non lisible par cet utilisateur (relance en root pour le détail)."
  fi
  echo "CPU : $(cpu_logical_cores) logique(s), environ $(cpu_physical_cores) physique(s) — $(cpu_speed_summary)"
  mem_kb=$(awk '/^MemAvailable:/ { print $2 }' /proc/meminfo 2>/dev/null || true)
  if [[ "$mem_kb" =~ ^[0-9]+$ ]]; then
    echo "RAM disponible : environ $((mem_kb / 1024)) MB"
  fi
  if command -v curl >/dev/null 2>&1 && command -v jq >/dev/null 2>&1 && ollama_api_ready; then
    installed=$(installed_model_names 2>/dev/null || true)
    saved_default=$(saved_model_name)
    if [[ -n "$installed" ]]; then
      echo "Modèles présents pris en compte par l'optimisation globale :"
      while IFS= read -r model; do
        [[ -n "$model" ]] || continue
        if [[ "$(normalize_model_name "$model")" == "$(normalize_model_name "$saved_default")" ]]; then
          echo "  - $model [défaut]"
        else
          echo "  - $model"
        fi
      done <<< "$installed"
    else
      echo "Aucun modèle téléchargé présent pour le moment."
    fi
    loaded=$(loaded_model_names 2>/dev/null || true)
    if [[ -n "$loaded" ]]; then
      echo "Modèle(s) chargé(s) en RAM : $(printf '%s' "$loaded" | tr '\n' ' ')"
    else
      echo "Aucun modèle chargé en RAM pour le moment."
    fi
  else
    echo "API Ollama locale non joignable : liste des modèles présents et état RAM inconnus."
  fi
  cat <<'EOF'

Portée : ces réglages vivent dans le processus serveur Ollama. Ils s'appliquent donc à tous les modèles
présents servis par Ollama, pas seulement au modèle par défaut. "ola bench" sans nom de modèle les teste
tous, un par un ; "ola speed apply/reset" mesure et vérifie aussi chaque modèle présent, un par un.
Ce que "ola speed apply" change (avec mesure avant/après et retour arrière auto si Ollama ne répond plus) :
  OLLAMA_FLASH_ATTENTION=1 et OLLAMA_KV_CACHE_TYPE=q8_0 (cache KV ~2x plus léger que f16, gain RAM et vitesse possible).
Ce qu'il ne change jamais : OLLAMA_NUM_PARALLEL=1, OLLAMA_MAX_LOADED_MODELS=1 et le contexte,
car les augmenter coûterait de la RAM sans rendre une requête seule plus rapide.
Le keep-alive serveur (5m par défaut) n'est pas touché par Pack Speed ; il se règle à part, délibérément :
ola fluid keepalive <durée|reset> (voir ola fluid pour l'état complet et le compromis RAM).
Revenir en arrière : ola speed reset
Mesurer avant/après : ola bench (tous les modèles présents) ou ola bench <modèle> (un seul)
Fluidité ressentie (1er token, streaming local/public) : ola bench --stream, ola fluid warm, ola fluid preset
EOF
}

rollback_speed_config(){
  local backup=$1 prev_existed=$2 prev_value=$3
  cp -a "$backup" "$SUP_DIR/ollama.conf" 2>/dev/null || true
  chmod 600 "$SUP_DIR/ollama.conf" 2>/dev/null || true
  if [[ "$prev_existed" -eq 1 ]]; then
    printf '%s\n' "$prev_value" > "$SPEED_FILE" 2>/dev/null || true
    chmod 600 "$SPEED_FILE" 2>/dev/null || true
  else
    rm -f "$SPEED_FILE"
  fi
  supervisor_apply >/dev/null 2>&1 || true
  supervisor_ctl start ollama >/dev/null 2>&1 || true
  wait_for_supervisor_program ollama 30 >/dev/null 2>&1 || true
  wait_for_ollama_api 30 || true
}

verify_model_chat(){
  local model=$1 payload
  is_valid_model_name "$model" || return 1
  payload=$(jq -cn --arg model "$model" '{model:$model, messages:[{role:"user", content:"Reply only with OK."}], stream:false, options:{num_predict:16}}') || return 1
  curl -fsS --max-time 180 http://127.0.0.1:11434/api/chat \
    -H 'Content-Type: application/json' -d "$payload" >/dev/null 2>&1
}

# One short speed measurement for a model. Prefers think:false, then falls
# back to the model's default behaviour for models that refuse think:false.
measure_model_once(){
  local model=$1 res
  if res=$(bench_run "$model" off); then
    printf '%s' "$res"
    return 0
  fi
  if res=$(bench_run "$model" default); then
    printf '%s' "$res"
    return 0
  fi
  return 1
}

apply_speed_mode(){
  local target=$1 ollama_bin current installed saved_default ordered backup prev_speed_existed=0 prev_speed_value=""
  local -a present_models=() before_labels=() before_ok=() after_labels=()
  local model res idx regression_models="" verified_after=0 already_failing=0 bench_status=0
  select_supervisor_paths
  [[ -f "$SUP_DIR/ollama.conf" ]] || die "Ollama Supervisor config not found: $SUP_DIR/ollama.conf. Run setup first: ola setup"
  ollama_bin=$(ollama_bin_path) || die "Ollama binary not found. Run setup first: ola setup"
  require_commands curl jq
  ensure_service_users
  current=$(saved_speed_mode)

  if ! supervisor_program_running ollama; then
    info "Ollama is not RUNNING; starting it before applying the speed mode..."
    supervisor_ctl start ollama 2>/dev/null || supervisor_ctl restart ollama \
      || die "Could not start Ollama. Check: ola logs"
    wait_for_supervisor_program ollama 30 || die "Ollama did not reach RUNNING. Check: ola logs"
  fi
  ollama_api_ready || die "Ollama API is not answering. Try: ola recover"

  installed=$(installed_model_names) || die "Could not read the installed model list from Ollama."
  saved_default=$(saved_model_name)
  ordered=$(ordered_present_model_names "$installed" "$saved_default")
  while IFS= read -r model; do
    [[ -n "$model" ]] || continue
    if is_valid_model_name "$model"; then
      present_models+=("$model")
    else
      warn "Ignoring an installed model with an unexpected name: $model"
    fi
  done <<< "$ordered"

  if [[ "$current" == "$target" ]] && speed_config_matches "$target"; then
    ok "Speed mode is already set: $target (Supervisor config already matches, server-wide)."
    if [[ ${#present_models[@]} -eq 0 ]]; then
      show_speed
      return 0
    fi
    info "No config change or restart is needed; checking every present model in the current mode so newly added models are included..."
    bench_status=0
    run_bench "" || bench_status=$?
    return "$bench_status"
  fi

  if [[ ${#present_models[@]} -gt 0 ]]; then
    info "Portée globale : ${#present_models[@]} modèle(s) présent(s) pris en compte, un par un : $(printf '%s' "$installed" | tr '\n' ' ')"
    info "Measuring current speed for every present model before the change (short test, one model at a time)..."
    for idx in "${!present_models[@]}"; do
      model="${present_models[$idx]}"
      stop_loaded_models_except_soft "$model"
      if res=$(measure_model_once "$model"); then
        before_labels[idx]=$(printf '%s' "$res" | cut -f4)
        before_ok[idx]=1
        info "Before [$model]: generation ${before_labels[$idx]} tok/s"
      elif verify_model_chat "$model"; then
        before_labels[idx]="répond, vitesse non mesurée"
        before_ok[idx]=1
        warn "Before [$model]: the model answers, but its short speed measurement failed."
      else
        before_labels[idx]="échec avant changement"
        before_ok[idx]=0
        warn "Before [$model]: this model did not answer before the change; it will be rechecked after, without forcing a rollback by itself."
      fi
    done
  else
    warn "No downloaded model is present; applying the server-wide speed mode with an API-only verification."
  fi

  backup=$(mktemp) || die "Could not create a temporary backup of the Ollama Supervisor config."
  cp -a "$SUP_DIR/ollama.conf" "$backup" || { rm -f "$backup"; die "Could not back up $SUP_DIR/ollama.conf."; }
  if [[ -f "$SPEED_FILE" ]]; then
    prev_speed_existed=1
    prev_speed_value=$(head -n 1 "$SPEED_FILE" 2>/dev/null || true)
  fi

  info "Applying server-wide speed mode: $target (applies to every model served by Ollama, not only the default)"
  save_speed_mode "$target"
  write_ollama_supervisor_config "$ollama_bin" "$target"
  supervisor_apply
  supervisor_ctl start ollama >/dev/null 2>&1 || true
  if ! wait_for_supervisor_program ollama 30 || ! wait_for_ollama_api 30; then
    warn "Ollama did not come back after applying speed mode $target; restoring the previous configuration..."
    rollback_speed_config "$backup" "$prev_speed_existed" "$prev_speed_value"
    rm -f "$backup"
    die "Speed mode $target could not be applied; the previous Ollama configuration was restored. Check: ola logs"
  fi

  if [[ ${#present_models[@]} -gt 0 ]]; then
    info "Verifying and measuring every present model after the change (same short test, one model at a time)..."
    for idx in "${!present_models[@]}"; do
      model="${present_models[$idx]}"
      stop_loaded_models_except_soft "$model"
      if res=$(measure_model_once "$model"); then
        after_labels[idx]=$(printf '%s' "$res" | cut -f4)
        verified_after=$((verified_after + 1))
      elif verify_model_chat "$model"; then
        after_labels[idx]="répond, vitesse non mesurée"
        verified_after=$((verified_after + 1))
        warn "After [$model]: the model answers, but its short speed measurement failed."
      else
        after_labels[idx]="échec après changement"
        if [[ "${before_ok[$idx]:-0}" -eq 1 ]]; then
          regression_models="${regression_models} ${model}"
        else
          already_failing=$((already_failing + 1))
        fi
      fi
      echo "[$model] Avant : ${before_labels[$idx]:-non mesuré} · Après : ${after_labels[$idx]:-non mesuré}"
    done

    if [[ -n "$regression_models" ]]; then
      warn "At least one model that worked before no longer answers after speed mode $target:${regression_models}; restoring the previous configuration..."
      rollback_speed_config "$backup" "$prev_speed_existed" "$prev_speed_value"
      rm -f "$backup"
      die "Speed mode $target failed verification for:${regression_models}. The previous Ollama configuration was restored. Check: ola logs"
    fi
    if [[ "$already_failing" -gt 0 ]]; then
      warn "$already_failing present model(s) were already failing before the change and still fail; they did not trigger a rollback."
    fi
    ok "Verification passed for $verified_after/${#present_models[@]} present model(s) with speed mode: $target"
  else
    ok "Ollama API verification passed with speed mode: $target (no downloaded model to chat-test)"
  fi

  rm -f "$backup"
  ok "Speed mode is now: $target, for every model served by Ollama. Full per-model comparison anytime with: ola bench"
  if [[ "$target" == "speed" ]]; then
    echo "Actif pour tout le serveur Ollama : OLLAMA_FLASH_ATTENTION=1, OLLAMA_KV_CACHE_TYPE=q8_0. Inchangés : contexte $OLLAMA_CONTEXT_LENGTH, 1 modèle chargé, 1 requête parallèle, keep-alive 5m."
  else
    echo "Configuration équilibrée restaurée pour tout le serveur Ollama (pas de Flash Attention, cache KV par défaut). Inchangés : contexte, parallélisme et keep-alive."
  fi
}

show_doctor(){
  local failures=0 warnings=0 cmd program version_json ollama_version tags_json ps_json model_names loaded_names
  local model home_dir mem_kb disk_kb log_bytes public_url state validate_output speed_flash speed_kv speed_keepalive tui_version
  select_supervisor_paths
  echo "--- Ola doctor ---"

  for cmd in curl jq supervisorctl supervisord; do
    if command -v "$cmd" >/dev/null 2>&1; then
      ok "$cmd found"
    else
      err "$cmd not found"
      failures=$((failures + 1))
    fi
  done
  if ollama_bin_path >/dev/null 2>&1; then
    ok "Ollama binary found: $(ollama_bin_path)"
  else
    err "Ollama binary not found"
    failures=$((failures + 1))
  fi
  if command -v cloudflared >/dev/null 2>&1; then
    ok "cloudflared found: $(cloudflared --version 2>&1 | head -n 1)"
  else
    err "cloudflared binary not found"
    failures=$((failures + 1))
  fi

  if [[ -f "$SUP_CONF" ]]; then
    ok "Supervisor config: $SUP_CONF"
  else
    err "Supervisor config not found: $SUP_CONF"
    failures=$((failures + 1))
  fi
  if supervisor_is_running; then
    ok "Supervisor is responding"
  else
    err "Supervisor is not responding (try: ola recover)"
    failures=$((failures + 1))
  fi

  for program in ollama cloudflared-ollama; do
    if supervisor_program_running "$program"; then
      ok "$program is RUNNING"
    else
      err "$program is not RUNNING (try: ola recover)"
      failures=$((failures + 1))
    fi
  done
  if [[ -f "$SUP_DIR/ollama-watchdog.conf" ]]; then
    if supervisor_program_running ollama-watchdog; then
      ok "ollama-watchdog is RUNNING"
    else
      warn "ollama-watchdog is configured but not RUNNING (try: ola start)"
      warnings=$((warnings + 1))
    fi
  else
    warn "Health watchdog is not installed yet (run: ola start)"
    warnings=$((warnings + 1))
  fi

  if tui_environment_ready; then
    tui_version=$(tui_textual_version)
    ok "Textual TUI installed: Textual $tui_version (launch: ola tui)"
  else
    warn "Textual TUI is not installed/ready (classic ola commands still work; repair: sudo ola tui install)"
    warnings=$((warnings + 1))
  fi

  version_json=$(curl -fsS --max-time 10 http://127.0.0.1:11434/api/version 2>/dev/null || true)
  if [[ -n "$version_json" ]]; then
    ollama_version=""
    if command -v jq >/dev/null 2>&1; then
      ollama_version=$(printf '%s' "$version_json" | jq -r '.version // empty' 2>/dev/null || true)
    fi
    [[ -n "$ollama_version" ]] || ollama_version="$version_json"
    ok "Ollama local API: $ollama_version"
  else
    err "Ollama local API is not answering on 127.0.0.1:11434"
    failures=$((failures + 1))
  fi

  model=$(saved_model_name)
  home_dir=$(ollama_home_for_status)
  tags_json=$(curl -fsS --max-time 10 http://127.0.0.1:11434/api/tags 2>/dev/null || true)
  model_names=""
  loaded_names=""
  if [[ -n "$tags_json" ]]; then
    if command -v jq >/dev/null 2>&1; then
      model_names=$(printf '%s' "$tags_json" | jq -r '.models[]?.name // empty' 2>/dev/null || true)
      ps_json=$(curl -fsS --max-time 10 http://127.0.0.1:11434/api/ps 2>/dev/null || true)
      loaded_names=$(printf '%s' "$ps_json" | jq -r '.models[]?.name // empty' 2>/dev/null || true)
    else
      model_names=$(printf '%s' "$tags_json" | grep -o '"name"[[:space:]]*:[[:space:]]*"[^"]*"' | sed 's/.*"\([^"]*\)"$/\1/' || true)
    fi
  fi
  if [[ -n "$model_names" ]]; then
    ok "Installed models: $(printf '%s' "$model_names" | tr '\n' ' ')"
    if printf '%s\n' "$model_names" | grep -Fxq "$model"; then
      ok "Default model is installed: $model"
    else
      err "Default model is not installed: $model"
      failures=$((failures + 1))
    fi
  elif [[ -n "$version_json" ]]; then
    warn "Could not list installed Ollama models"
    warnings=$((warnings + 1))
  fi
  if [[ -n "$loaded_names" ]]; then
    ok "Currently loaded: $(printf '%s' "$loaded_names" | tr '\n' ' ')"
  else
    info "No model currently loaded (it will load on the next request)."
  fi

  if supervisor_program_running cloudflared-ollama; then
    state=0
    cloudflared_ready_state || state=$?
    if [[ "$state" -eq 0 ]]; then
      ok "cloudflared readiness endpoint reports ready"
    elif [[ "$state" -eq 1 ]]; then
      err "cloudflared is RUNNING but reports not ready"
      failures=$((failures + 1))
    else
      warn "cloudflared readiness endpoint unavailable; readiness is unknown"
      warnings=$((warnings + 1))
    fi
  fi

  if [[ -f "$CF_CONF_DIR/config.yml" ]] && command -v cloudflared >/dev/null 2>&1; then
    if validate_output=$(cloudflared tunnel --config "$CF_CONF_DIR/config.yml" ingress validate 2>&1); then
      ok "Cloudflare ingress config is valid"
    else
      warn "Cloudflare ingress validation did not pass: $validate_output"
      warnings=$((warnings + 1))
    fi
  fi

  mem_kb=$(awk '/^MemAvailable:/ { print $2 }' /proc/meminfo 2>/dev/null || true)
  if [[ "$mem_kb" =~ ^[0-9]+$ ]]; then
    if [[ "$mem_kb" -lt 524288 ]]; then
      warn "Available RAM is low: about $((mem_kb / 1024)) MB"
      warnings=$((warnings + 1))
    else
      ok "Available RAM: about $((mem_kb / 1024)) MB"
    fi
  else
    warn "Could not determine available RAM"
    warnings=$((warnings + 1))
  fi

  speed_flash=$(ollama_config_value OLLAMA_FLASH_ATTENTION)
  speed_kv=$(ollama_config_value OLLAMA_KV_CACHE_TYPE)
  speed_keepalive=$(ollama_config_value OLLAMA_KEEP_ALIVE)
  info "Speed mode: $(saved_speed_mode) (Flash Attention: ${speed_flash:-off}, KV cache: ${speed_kv:-default f16}) — details: ola speed, measure: ola bench"
  info "Fluid keep-alive: saved $(saved_keep_alive), effective ${speed_keepalive:-unknown} — details: ola fluid, streaming measure: ola bench --stream"

  disk_kb=$(free_kb "$home_dir")
  if [[ "$disk_kb" -gt 0 && "$disk_kb" -lt 1048576 ]]; then
    warn "Free disk space on $home_dir is low: about $((disk_kb / 1024)) MB"
    warnings=$((warnings + 1))
  elif [[ "$disk_kb" -gt 0 ]]; then
    ok "Free disk space on $home_dir: about $((disk_kb / 1024)) MB"
  fi

  log_bytes=0
  local f size
  for f in "$LOG_DIR"/*.log; do
    [[ -f "$f" ]] || continue
    size=$(file_size "$f")
    log_bytes=$((log_bytes + size))
  done
  ok "Supervisor logs currently use about $((log_bytes / 1024 / 1024)) MB (rotation is enabled)."

  if [[ -r "$URL_FILE" ]]; then
    public_url=$(head -n 1 "$URL_FILE")
    if [[ -n "$public_url" ]]; then
      if https_url_ready "${public_url}/api/version"; then
        ok "Public URL answers: $public_url"
      else
        err "Public URL does not answer yet: $public_url"
        failures=$((failures + 1))
      fi
    else
      warn "Public URL file is empty: $URL_FILE"
      warnings=$((warnings + 1))
    fi
  elif [[ -f "$URL_FILE" ]]; then
    warn "Public URL is saved but is not readable by this user"
    warnings=$((warnings + 1))
  else
    warn "No public URL saved yet"
    warnings=$((warnings + 1))
  fi

  echo "--- Doctor summary: ${failures} failure(s), ${warnings} warning(s) ---"
  [[ "$failures" -eq 0 ]]
}

run_ola_test(){
  local failures=0 model version_json tags_json model_names payload response content public_url
  local start_ms end_ms elapsed_ms
  model=$(saved_model_name)
  echo "--- Ola test ---"
  info "Default model: $model"

  start_ms=$(date +%s%3N)
  if version_json=$(curl -fsS --max-time 15 http://127.0.0.1:11434/api/version 2>/dev/null); then
    end_ms=$(date +%s%3N)
    elapsed_ms=$((end_ms - start_ms))
    ok "Local Ollama API: $version_json (${elapsed_ms} ms)"
  else
    err "Local Ollama API failed"
    failures=$((failures + 1))
    echo "--- Test summary: FAILED ---"
    return 1
  fi

  if tags_json=$(curl -fsS --max-time 15 http://127.0.0.1:11434/api/tags 2>/dev/null); then
    model_names=""
    if command -v jq >/dev/null 2>&1; then
      model_names=$(printf '%s' "$tags_json" | jq -r '.models[]?.name // empty' 2>/dev/null || true)
    else
      model_names=$(printf '%s' "$tags_json" | grep -o '"name"[[:space:]]*:[[:space:]]*"[^"]*"' | sed 's/.*"\([^"]*\)"$/\1/' || true)
    fi
    if printf '%s\n' "$model_names" | grep -Fxq "$model"; then
      ok "Model is installed: $model"
    else
      err "Model is not installed: $model"
      failures=$((failures + 1))
    fi
  else
    err "Could not list Ollama models"
    failures=$((failures + 1))
  fi

  if command -v jq >/dev/null 2>&1; then
    payload=$(jq -cn --arg model "$model" '{model:$model, messages:[{role:"user", content:"Reply only with OK."}], stream:false}')
    start_ms=$(date +%s%3N)
    if response=$(curl -fsS --max-time 180 http://127.0.0.1:11434/api/chat -H 'Content-Type: application/json' -d "$payload" 2>/dev/null); then
      end_ms=$(date +%s%3N)
      elapsed_ms=$((end_ms - start_ms))
      content=$(printf '%s' "$response" | jq -r '.message.content // .response // empty' 2>/dev/null || true)
      [[ -n "$content" ]] || content="(empty response)"
      ok "Local chat test (${elapsed_ms} ms): $content"
    else
      err "Local chat test failed for model: $model"
      failures=$((failures + 1))
    fi
  else
    err "jq is required for the chat test"
    failures=$((failures + 1))
  fi

  if [[ -r "$URL_FILE" ]]; then
    public_url=$(head -n 1 "$URL_FILE")
    if [[ -n "$public_url" ]] && https_url_ready "${public_url}/api/version"; then
      ok "Public API answers: $public_url"
    else
      err "Public API does not answer: ${public_url:-unknown}"
      failures=$((failures + 1))
    fi
  else
    err "No readable public URL saved"
    failures=$((failures + 1))
  fi

  if [[ "$failures" -eq 0 ]]; then
    ok "All tests passed."
  else
    err "Test summary: ${failures} failure(s)."
  fi
  [[ "$failures" -eq 0 ]]
}

recover_services(){
  local want_ollama=0 want_cloudflared=0 state
  select_supervisor_paths
  [[ -f "$SUP_DIR/ollama.conf" ]] && want_ollama=1
  [[ -f "$SUP_DIR/cloudflared-ollama.conf" ]] && want_cloudflared=1
  if [[ "$want_ollama" -eq 0 && "$want_cloudflared" -eq 0 ]]; then
    die "No Ollama/cloudflared Supervisor programs are configured. Run setup first: ola setup"
  fi

  if [[ "$want_ollama" -eq 1 ]]; then
    if ! supervisor_program_running ollama; then
      info "Ollama is not RUNNING; starting it..."
      supervisor_ctl start ollama 2>/dev/null || supervisor_ctl restart ollama \
        || die "Could not start Ollama. Check: ola logs"
    fi
    wait_for_supervisor_program ollama 30 \
      || die "Ollama did not reach RUNNING during recover. Check: ola logs"
    if ! ollama_api_ready; then
      warn "Ollama is RUNNING but its API is not answering; restarting Ollama once..."
      supervisor_ctl restart ollama || die "Could not restart Ollama during recover."
      wait_for_supervisor_program ollama 30 \
        || die "Ollama did not reach RUNNING after recover restart."
      ollama_api_ready || die "Ollama API still does not answer after recover. Check: ola logs"
    fi
    ok "Ollama recovered and answering locally."
  fi

  if [[ "$want_cloudflared" -eq 1 ]]; then
    if ! supervisor_program_running cloudflared-ollama; then
      info "cloudflared-ollama is not RUNNING; starting it..."
      supervisor_ctl start cloudflared-ollama 2>/dev/null || supervisor_ctl restart cloudflared-ollama \
        || die "Could not start cloudflared. Check: ola logs"
    fi
    wait_for_supervisor_program cloudflared-ollama 30 \
      || die "cloudflared did not reach RUNNING during recover. Check: ola logs"
    state=0
    wait_cloudflared_ready 30 || state=$?
    if [[ "$state" -eq 1 ]]; then
      warn "cloudflared reports not ready; restarting it once..."
      supervisor_ctl restart cloudflared-ollama || die "Could not restart cloudflared during recover."
      wait_for_supervisor_program cloudflared-ollama 30 \
        || die "cloudflared did not reach RUNNING after recover restart."
      state=0
      wait_cloudflared_ready 60 || state=$?
      [[ "$state" -eq 1 ]] && die "cloudflared still reports not ready after recover. Check: ola logs"
    fi
    if [[ "$state" -eq 2 ]]; then
      warn "cloudflared is RUNNING; readiness endpoint was unavailable, so no restart was forced."
    else
      ok "cloudflared recovered and ready."
    fi
  fi

  echo
  show_status
  ok "Recover finished."
}

setup_all(){
  case "$CF_TUNNEL_PROTOCOL" in
    auto|http2|quic) ;;
    *) die "Invalid CF_TUNNEL_PROTOCOL='$CF_TUNNEL_PROTOCOL' (expected auto, http2 or quic)." ;;
  esac
  install_ola_command
  apt_update
  apt_install curl ca-certificates gnupg jq tar
  require_commands curl jq sha256sum tar awk sed grep find stat df
  if ! install_tui_environment; then
    warn "The optional Textual TUI could not be installed. Setup will continue: every classic ola command remains available, and the TUI can be repaired later with: sudo ola tui install"
  fi
  ensure_service_users
  ensure_supervisor_running
  ensure_watchdog
  install_ollama
  install_cloudflared
  ensure_service_users
  echo
  echo "Choose tunnel mode:"
  echo "  1) Quick Tunnel (random trycloudflare.com URL; easiest, temporary URL)"
  echo "  2) Named Tunnel (your domain + Cloudflare account; persistent hostname)"
  local mode
  if ! mode=$(prompt_value "Choice [1]: " "1"); then
    die "No input received for the tunnel mode; aborting instead of silently choosing a public Quick Tunnel."
  fi
  case "$mode" in
    1) configure_quick_tunnel ;;
    2) configure_named_tunnel ;;
    *) die "Invalid choice." ;;
  esac
  echo
  show_status
  echo
  ok "Setup finished. Try: ola doctor, ola test, ola recover, ola logs"
  warn "Supervisor can restart processes, but 24/7 uptime still depends on the hosting platform keeping this container alive and starting Supervisor again after container restart."
}

# Optional Textual terminal interface.
#
# The Python application source lives in tui/ola_tui.py in the repository.
# build.sh embeds it below, so the published single-file artifact can extract
# it next to the installed ola script. The Bash engine remains authoritative:
# the TUI only reads the local Ollama API and invokes the installed ola CLI
# for actions, preserving all existing safety checks and confirmations.

write_ola_tui_python_file(){
  local target=$1 tmp
  tmp=$(mktemp "${target}.tmp-XXXXXX") || return 1
  cat > "$tmp" <<'OLA_TUI_PY'
#!/usr/bin/env python3
"""Ola terminal interface (Textual).

The Bash ``ola`` program remains the engine and the safety boundary. This
application only reads the local Ollama HTTP API and delegates actions to the
installed ``ola`` CLI. It deliberately does not reimplement model deletion,
model switching, Supervisor management or Pack Speed/Fluidité logic.
"""

from __future__ import annotations

import asyncio
import json
import os
import re
import shutil
import subprocess
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from rich.text import Text
from textual.app import App, ComposeResult
from textual.binding import Binding
from textual.containers import Horizontal, Vertical
from textual.screen import ModalScreen, Screen
from textual.widgets import Button, DataTable, Footer, Header, Input, RichLog, Static, TextArea

API_URL = os.environ.get("OLA_TUI_API_URL", "http://127.0.0.1:11434").rstrip("/")
CLI = os.environ.get("OLA_TUI_CLI") or shutil.which("ola") or "/usr/local/bin/ola"
URL_FILE = Path("/etc/ollama-cloudflare-url")
MODEL_FILE = Path("/etc/ollama-cloudflare-model")
SPEED_FILE = Path("/etc/ollama-cloudflare-speed")
KEEPALIVE_FILE = Path("/etc/ollama-cloudflare-keepalive")
DEFAULT_MODEL = "qwen3:1.7b"
LOG_FILES = [
    ("Ollama", Path("/var/log/supervisor/ollama.log")),
    ("Ollama erreurs", Path("/var/log/supervisor/ollama-error.log")),
    ("cloudflared", Path("/var/log/supervisor/cloudflared-ollama.log")),
    ("cloudflared erreurs", Path("/var/log/supervisor/cloudflared-ollama-error.log")),
    ("Watchdog", Path("/var/log/supervisor/ollama-watchdog.log")),
]
MODEL_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._/:@-]*$")
THEME_CYCLE = [
    "textual-dark",
    "catppuccin-mocha",
    "dracula",
    "nord",
    "tokyo-night",
    "gruvbox",
    "textual-light",
]


def normalize_model(name: str) -> str:
    name = name.strip()
    last = name.rsplit("/", 1)[-1]
    return name if ":" in last else f"{name}:latest"


def valid_model(name: str) -> bool:
    return bool(MODEL_RE.fullmatch(name.strip()))


def read_first_line(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="ignore").splitlines()[0].strip()
    except (OSError, IndexError):
        return ""


def format_bytes(value: Any) -> str:
    try:
        size = float(value or 0)
    except (TypeError, ValueError):
        return "inconnue"
    if size <= 0:
        return "inconnue"
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if size < 1024 or unit == "TB":
            return f"{size:.1f} {unit}" if unit != "B" else f"{int(size)} B"
        size /= 1024
    return "inconnue"


def format_expiry(value: str) -> str:
    if not value:
        return "—"
    return value.replace("T", " ")[:19]


def http_json(path: str, payload: dict[str, Any] | None = None, timeout: float = 6) -> Any:
    data = None
    headers = {"Content-Type": "application/json"}
    method = "GET"
    if payload is not None:
        data = json.dumps(payload).encode("utf-8")
        method = "POST"
    request = urllib.request.Request(
        f"{API_URL}{path}", data=data, headers=headers, method=method
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:
        return json.loads(response.read().decode("utf-8"))


def http_status(url: str, timeout: float = 2) -> int | None:
    try:
        request = urllib.request.Request(url, method="GET")
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return int(response.status)
    except urllib.error.HTTPError as exc:
        return int(exc.code)
    except (OSError, ValueError):
        return None


def parse_meminfo() -> dict[str, int]:
    values: dict[str, int] = {}
    try:
        for line in Path("/proc/meminfo").read_text(encoding="utf-8").splitlines():
            if ":" not in line:
                continue
            key, raw = line.split(":", 1)
            parts = raw.strip().split()
            if parts and parts[0].isdigit():
                values[key] = int(parts[0]) * 1024
    except OSError:
        pass
    return values


def supervisor_status() -> dict[str, str]:
    executable = shutil.which("supervisorctl")
    if not executable:
        return {}
    try:
        result = subprocess.run(
            [executable, "status"],
            text=True,
            capture_output=True,
            timeout=3,
            check=False,
        )
    except (OSError, subprocess.SubprocessError):
        return {}
    statuses: dict[str, str] = {}
    for line in result.stdout.splitlines():
        parts = line.split()
        if len(parts) >= 2:
            statuses[parts[0]] = parts[1]
    return statuses


@dataclass
class ModelInfo:
    name: str
    size: int = 0
    digest: str = ""
    family: str = ""
    parameter_size: str = ""
    quantization: str = ""
    loaded: bool = False
    loaded_size: int = 0
    expires_at: str = ""
    context_length: int | None = None


@dataclass
class Snapshot:
    api_ok: bool = False
    version: str = "inconnue"
    error: str = ""
    models: list[ModelInfo] = field(default_factory=list)
    default_model: str = DEFAULT_MODEL
    public_url: str = ""
    speed_mode: str = "balanced"
    keepalive: str = "5m"
    services: dict[str, str] = field(default_factory=dict)
    cloudflared_ready: int | None = None
    mem_total: int = 0
    mem_available: int = 0
    swap_total: int = 0
    swap_free: int = 0


def fetch_snapshot() -> Snapshot:
    snapshot = Snapshot()
    snapshot.default_model = read_first_line(MODEL_FILE) or DEFAULT_MODEL
    snapshot.public_url = read_first_line(URL_FILE)
    snapshot.speed_mode = read_first_line(SPEED_FILE) or "balanced"
    if snapshot.speed_mode not in {"balanced", "speed"}:
        snapshot.speed_mode = "balanced"
    snapshot.keepalive = read_first_line(KEEPALIVE_FILE) or "5m"

    mem = parse_meminfo()
    snapshot.mem_total = mem.get("MemTotal", 0)
    snapshot.mem_available = mem.get("MemAvailable", 0)
    snapshot.swap_total = mem.get("SwapTotal", 0)
    snapshot.swap_free = mem.get("SwapFree", 0)
    snapshot.services = supervisor_status()
    snapshot.cloudflared_ready = http_status("http://127.0.0.1:20241/ready")

    models: dict[str, ModelInfo] = {}
    try:
        version_data = http_json("/api/version", timeout=4)
        snapshot.version = str(version_data.get("version") or "inconnue")
        snapshot.api_ok = True
        tags = http_json("/api/tags", timeout=6)
        for item in tags.get("models") or []:
            name = str(item.get("name") or "")
            if not name:
                continue
            details = item.get("details") or {}
            models[name] = ModelInfo(
                name=name,
                size=int(item.get("size") or 0),
                digest=str(item.get("digest") or ""),
                family=str(details.get("family") or ""),
                parameter_size=str(details.get("parameter_size") or ""),
                quantization=str(details.get("quantization_level") or ""),
            )
        try:
            running = http_json("/api/ps", timeout=6)
            for item in running.get("models") or []:
                name = str(item.get("name") or "")
                if not name:
                    continue
                model = models.setdefault(name, ModelInfo(name=name))
                model.loaded = True
                model.loaded_size = int(item.get("size") or 0)
                model.expires_at = str(item.get("expires_at") or "")
                context = item.get("context_length")
                model.context_length = int(context) if context else None
        except Exception:
            # The model table remains useful with /api/tags alone.
            pass
    except Exception as exc:  # API down / malformed response
        snapshot.error = str(exc) or exc.__class__.__name__

    default_norm = normalize_model(snapshot.default_model)
    snapshot.models = sorted(
        models.values(),
        key=lambda model: (
            normalize_model(model.name) == default_norm,
            model.name.lower(),
        ),
    )
    return snapshot


def fetch_show(model: str) -> dict[str, Any]:
    if not valid_model(model):
        return {}
    try:
        data = http_json("/api/show", {"model": model}, timeout=8)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def run_cli(args: list[str], timeout: int = 900) -> tuple[int, str]:
    if not CLI:
        return 127, "Commande ola introuvable."
    try:
        result = subprocess.run(
            [CLI, *args],
            text=True,
            capture_output=True,
            timeout=timeout,
            check=False,
        )
    except FileNotFoundError:
        return 127, f"Commande ola introuvable : {CLI}"
    except subprocess.TimeoutExpired as exc:
        output = (exc.stdout or "") + (exc.stderr or "")
        if isinstance(output, bytes):
            output = output.decode("utf-8", errors="ignore")
        return 124, f"{output}\n\nCommande interrompue après {timeout} secondes."
    except OSError as exc:
        return 1, f"Impossible de lancer ola : {exc}"
    output = "\n".join(
        part.strip() for part in (result.stdout, result.stderr) if part and part.strip()
    )
    return result.returncode, output or "(aucune sortie)"


class ConfirmScreen(ModalScreen[bool]):
    BINDINGS = [
        Binding("escape", "cancel", "Annuler"),
        Binding("q", "cancel", "Annuler"),
    ]

    def __init__(self, title: str, message: str, confirm_label: str = "Confirmer"):
        super().__init__()
        self.dialog_title = title
        self.dialog_message = message
        self.confirm_label = confirm_label

    def compose(self) -> ComposeResult:
        with Vertical(classes="dialog"):
            yield Static(self.dialog_title, classes="dialog-title")
            yield Static(self.dialog_message, classes="dialog-message")
            with Horizontal(classes="dialog-buttons"):
                yield Button(self.confirm_label, id="confirm", variant="error")
                yield Button("Annuler", id="cancel", variant="primary")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        self.dismiss(event.button.id == "confirm")

    def action_cancel(self) -> None:
        self.dismiss(False)


class AddModelScreen(ModalScreen[str | None]):
    BINDINGS = [Binding("escape", "cancel", "Annuler")]

    def compose(self) -> ComposeResult:
        with Vertical(classes="dialog"):
            yield Static("Ajouter et utiliser un modèle", classes="dialog-title")
            yield Static(
                "Le modèle sera téléchargé si nécessaire, puis chargé. Les autres modèles seront déchargés de la RAM par ola use.",
                classes="dialog-message",
            )
            yield Input(placeholder="Exemple : qwen3:0.6b", id="model-name")
            with Horizontal(classes="dialog-buttons"):
                yield Button("Télécharger et utiliser", id="add", variant="success")
                yield Button("Annuler", id="cancel", variant="primary")

    def on_mount(self) -> None:
        self.query_one("#model-name", Input).focus()

    def action_cancel(self) -> None:
        self.dismiss(None)

    def submit(self) -> None:
        value = self.query_one("#model-name", Input).value.strip()
        if not valid_model(value):
            self.app.notify("Nom de modèle invalide.", severity="error")
            return
        self.dismiss(value)

    def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.id == "add":
            self.submit()
        else:
            self.dismiss(None)

    def on_input_submitted(self, _event: Input.Submitted) -> None:
        self.submit()


class OutputScreen(Screen):
    BINDINGS = [
        Binding("escape", "close", "Fermer"),
        Binding("q", "close", "Fermer"),
    ]

    def __init__(self, title: str, content: str):
        super().__init__()
        self.output_title = title
        self.output_content = content

    def compose(self) -> ComposeResult:
        yield Header(show_clock=True)
        with Vertical():
            yield Static(self.output_title, id="output-title")
            yield RichLog(id="output-log", highlight=False, markup=False, wrap=True)
        yield Footer()

    def on_mount(self) -> None:
        log = self.query_one("#output-log", RichLog)
        log.write(self.output_content)
        log.scroll_home(animate=False)

    def action_close(self) -> None:
        self.app.pop_screen()


class LogsScreen(Screen):
    BINDINGS = [
        Binding("escape", "close", "Fermer"),
        Binding("q", "close", "Fermer"),
        Binding("r", "refresh_log", "Rafraîchir"),
        Binding("1", "select_log(0)", "Ollama"),
        Binding("2", "select_log(1)", "Erreurs"),
        Binding("3", "select_log(2)", "Tunnel"),
        Binding("4", "select_log(3)", "Tunnel err."),
        Binding("5", "select_log(4)", "Watchdog"),
    ]

    def __init__(self):
        super().__init__()
        self.current_index = 0

    def compose(self) -> ComposeResult:
        yield Header(show_clock=True)
        with Vertical():
            yield Static("", id="log-title")
            yield TextArea("", id="log-content", read_only=True, show_line_numbers=True)
        yield Footer()

    def on_mount(self) -> None:
        self.show_current()

    def show_current(self) -> None:
        name, path = LOG_FILES[self.current_index]
        self.query_one("#log-title", Static).update(
            f"Journal {name} — {path}  (touches 1-5, r rafraîchir, q fermer)"
        )
        area = self.query_one("#log-content", TextArea)
        try:
            data = path.read_bytes()[-150_000:]
            content = data.decode("utf-8", errors="replace")
            if not content:
                content = "(fichier vide)"
        except OSError as exc:
            content = f"Journal illisible : {exc}\nEssaie de lancer la TUI avec les droits root."
        area.load_text(content)
        area.scroll_end(animate=False)

    def action_refresh_log(self) -> None:
        self.show_current()

    def action_select_log(self, index: int) -> None:
        if 0 <= index < len(LOG_FILES):
            self.current_index = index
            self.show_current()

    def action_close(self) -> None:
        self.app.pop_screen()


class OlaTui(App):
    TITLE = "Ola"
    SUB_TITLE = "Ollama + Cloudflare"
    CSS = """
    Screen { background: $surface; }
    #banner {
        height: 3;
        padding: 0 1;
        background: $primary;
        color: $text;
        text-style: bold;
        content-align: left middle;
    }
    #top { height: 10; }
    #summary, #details {
        height: 10;
        padding: 0 1;
        border: solid $primary;
        overflow-y: auto;
    }
    #summary { width: 58%; }
    #details { width: 42%; border: solid $secondary; }
    #models { height: 1fr; border: solid $primary; }
    #status {
        height: 1;
        padding: 0 1;
        background: $boost;
        color: $text;
    }
    #output-title {
        height: 3;
        padding: 0 1;
        background: $primary;
        color: $text;
        text-style: bold;
        content-align: left middle;
    }
    #output-log { height: 1fr; border: solid $primary; }
    #log-title {
        height: 2;
        padding: 0 1;
        background: $primary;
        color: $text;
        text-style: bold;
        content-align: left middle;
    }
    #log-content { height: 1fr; border: solid $primary; }
    .dialog {
        width: 72;
        max-width: 92%;
        height: auto;
        max-height: 88%;
        margin: 4 6;
        padding: 1 2;
        background: $surface;
        border: thick $primary;
    }
    .dialog-title { text-style: bold; padding-bottom: 1; }
    .dialog-message { padding-bottom: 1; }
    .dialog-buttons { height: 3; align: right middle; }
    .dialog-buttons Button { margin-left: 1; }
    """

    BINDINGS = [
        Binding("q", "quit", "Quitter"),
        Binding("r", "refresh", "Rafraîchir"),
        Binding("u", "use_model", "Utiliser"),
        Binding("d", "delete_model", "Supprimer"),
        Binding("l", "unload_model", "Libérer RAM"),
        Binding("a", "add_model", "Ajouter"),
        Binding("w", "warm_model", "Préchauffer"),
        Binding("p", "preset_model", "Preset"),
        Binding("b", "bench_model", "Bench"),
        Binding("B", "stream_bench_model", "Bench streaming"),
        Binding("s", "speed_status", "Speed"),
        Binding("f", "fluid_status", "Fluidité"),
        Binding("g", "logs", "Logs"),
        Binding("t", "cycle_theme", "Thème"),
    ]

    def __init__(self):
        super().__init__()
        self.snapshot = Snapshot()
        self.current_model = ""
        self.show_cache: dict[str, dict[str, Any]] = {}
        self.refreshing = False
        self.action_running = False
        self.theme_index = 0
        # Keep direct references to the main-screen widgets. App.query_one()
        # searches the currently displayed screen, so background refreshes
        # would otherwise fail while an output, log or dialog screen is open.
        self.summary_widget: Static | None = None
        self.details_widget: Static | None = None
        self.models_table: DataTable | None = None
        self.status_widget: Static | None = None
        self.table_signature: tuple[object, ...] = ()

    def compose(self) -> ComposeResult:
        yield Header(show_clock=True)
        yield Static("OLA  ·  Ollama + Cloudflare Tunnel  ·  interface Textual", id="banner")
        with Horizontal(id="top"):
            yield Static("Chargement de l'état…", id="summary")
            yield Static("Sélectionne un modèle dans le tableau.", id="details")
        yield DataTable(id="models", zebra_stripes=True, cursor_type="row")
        yield Static("Démarrage…", id="status")
        yield Footer()

    async def on_mount(self) -> None:
        self.summary_widget = self.query_one("#summary", Static)
        self.details_widget = self.query_one("#details", Static)
        self.models_table = self.query_one("#models", DataTable)
        self.status_widget = self.query_one("#status", Static)
        table = self.models_table
        table.add_columns("État", "Modèle", "Taille", "RAM", "Défaut", "Expiration", "Contexte")
        self.set_interval(3.0, self._refresh_timer)
        await self.refresh_snapshot(force=True)

    def _refresh_timer(self) -> None:
        if not self.refreshing and not self.action_running:
            self.run_worker(self.refresh_snapshot(), group="refresh", exclusive=True)

    async def refresh_snapshot(self, force: bool = False) -> None:
        if self.refreshing:
            return
        self.refreshing = True
        try:
            snapshot = await asyncio.to_thread(fetch_snapshot)
            self.snapshot = snapshot
            self._render_snapshot()
            selected = self.selected_model_name()
            if selected and (force or selected not in self.show_cache):
                show = await asyncio.to_thread(fetch_show, selected)
                if show:
                    self.show_cache[selected] = show
                self._render_details()
        finally:
            self.refreshing = False

    def _render_snapshot(self) -> None:
        if self.summary_widget is None or self.models_table is None or self.status_widget is None:
            return
        snap = self.snapshot
        summary = Text()
        api_style = "bold green" if snap.api_ok else "bold red"
        summary.append("Ollama : ", style="bold")
        summary.append("● API OK" if snap.api_ok else "● API injoignable", style=api_style)
        summary.append(f"  ·  version {snap.version}\n")
        for program in ("ollama", "cloudflared-ollama", "ollama-watchdog"):
            state = snap.services.get(program, "état inconnu")
            style = "green" if state == "RUNNING" else "yellow" if state == "état inconnu" else "red"
            summary.append(f"{program} : ", style="bold")
            summary.append(f"{state}\n", style=style)
        summary.append("Tunnel local : ", style="bold")
        summary.append(
            "ready\n" if snap.cloudflared_ready == 200 else f"non confirmé ({snap.cloudflared_ready or 'aucune réponse'})\n"
        )
        summary.append("URL publique : ", style="bold")
        summary.append(f"{snap.public_url or 'non enregistrée'}\n")
        summary.append("Pack Speed : ", style="bold")
        summary.append(f"{snap.speed_mode}")
        summary.append("  ·  Keep-alive : ", style="bold")
        summary.append(f"{snap.keepalive}\n")
        if snap.mem_total:
            free_pct = int(snap.mem_available * 100 / snap.mem_total)
            filled = min(20, max(0, int((100 - free_pct) * 20 / 100)))
            bar = "█" * filled + "░" * (20 - filled)
            summary.append("RAM : ", style="bold")
            summary.append(
                f"{format_bytes(snap.mem_available)} libres / {format_bytes(snap.mem_total)} [{bar}] {free_pct}%\n"
            )
        if snap.swap_total:
            summary.append("Swap : ", style="bold")
            summary.append(f"{format_bytes(snap.swap_free)} libres / {format_bytes(snap.swap_total)}\n")
        summary.append("Accès : ", style="bold")
        summary.append(
            "root (actions actives)" if hasattr(os, "geteuid") and os.geteuid() == 0 else "non-root (ola refusera les actions protégées)"
        )
        if snap.error:
            summary.append(f"\nErreur API : {snap.error}", style="red")
        self.summary_widget.update(summary)

        table = self.models_table
        previous = self.current_model
        default_norm = normalize_model(snap.default_model)
        table_signature = tuple(
            (
                model.name,
                model.size,
                model.loaded,
                model.loaded_size,
                model.expires_at,
                model.context_length,
                normalize_model(model.name) == default_norm,
            )
            for model in snap.models
        )
        # Avoid rebuilding the table every three seconds when nothing changed:
        # it would reset the cursor/scroll while the user is navigating.
        if table_signature != self.table_signature:
            self.table_signature = table_signature
            table.clear()
            for model in snap.models:
                is_default = normalize_model(model.name) == default_norm
                table.add_row(
                    "● RAM" if model.loaded else "○ disque",
                    model.name,
                    format_bytes(model.size),
                    format_bytes(model.loaded_size) if model.loaded else "—",
                    "défaut" if is_default else "—",
                    format_expiry(model.expires_at) if model.loaded else "—",
                    str(model.context_length or "—"),
                    key=model.name,
                )
            if not snap.models:
                table.add_row("—", "Aucun modèle téléchargé", "—", "—", "—", "—", "—", key="__empty__")
                self.current_model = ""
            else:
                names = [model.name for model in snap.models]
                target = previous if previous in names else names[-1]
                self.current_model = target
                try:
                    table.move_cursor(row=names.index(target), column=0, animate=False)
                except Exception:
                    pass
        status = (
            f"{len(snap.models)} modèle(s) · défaut : {snap.default_model} · "
            f"CLI : {CLI} · r rafraîchir · t thème"
        )
        self.status_widget.update(status)
        self._render_details()

    def selected_model_name(self) -> str:
        if self.models_table is None:
            return self.current_model
        table = self.models_table
        try:
            cell_key = table.coordinate_to_cell_key(table.cursor_coordinate)
            value = str(cell_key.row_key.value or "")
            if value and value != "__empty__":
                self.current_model = value
        except Exception:
            pass
        return self.current_model

    def _render_details(self) -> None:
        if self.details_widget is None:
            return
        name = self.selected_model_name()
        details_widget = self.details_widget
        if not name:
            details_widget.update("Aucun modèle sélectionné.")
            return
        model = next((item for item in self.snapshot.models if item.name == name), None)
        show = self.show_cache.get(name, {})
        show_details = show.get("details") or {}
        capabilities = show.get("capabilities") or []
        text = Text()
        text.append("Modèle sélectionné\n", style="bold underline")
        text.append(f"{name}\n\n", style="bold")
        if model:
            text.append("État : ", style="bold")
            text.append("chargé en RAM\n" if model.loaded else "sur disque seulement\n")
            text.append("Taille disque : ", style="bold")
            text.append(f"{format_bytes(model.size)}\n")
            if model.loaded:
                text.append("Taille RAM déclarée : ", style="bold")
                text.append(f"{format_bytes(model.loaded_size)}\n")
                text.append("Expiration keep-alive : ", style="bold")
                text.append(f"{format_expiry(model.expires_at)}\n")
        parameter_size = str(show_details.get("parameter_size") or (model.parameter_size if model else ""))
        family = str(show_details.get("family") or (model.family if model else ""))
        quantization = str(show_details.get("quantization_level") or (model.quantization if model else ""))
        if parameter_size:
            text.append("Paramètres : ", style="bold")
            text.append(f"{parameter_size}\n")
        if family:
            text.append("Famille : ", style="bold")
            text.append(f"{family}\n")
        if quantization:
            text.append("Quantification : ", style="bold")
            text.append(f"{quantization}\n")
        if capabilities:
            text.append("Capacités : ", style="bold")
            text.append(", ".join(str(value) for value in capabilities) + "\n")
        default_norm = normalize_model(self.snapshot.default_model)
        text.append("Défaut ola : ", style="bold")
        text.append("oui\n" if normalize_model(name) == default_norm else "non\n")
        text.append("\nActions : u utiliser · d supprimer · l libérer RAM · w préchauffer · p preset · b bench")
        details_widget.update(text)

    async def on_data_table_row_highlighted(self, _event: DataTable.RowHighlighted) -> None:
        name = self.selected_model_name()
        if name and name not in self.show_cache:
            show = await asyncio.to_thread(fetch_show, name)
            if show:
                self.show_cache[name] = show
        self._render_details()

    def _require_model(self) -> str:
        name = self.selected_model_name()
        if not name or not valid_model(name):
            self.notify("Aucun modèle sélectionné.", severity="warning")
            return ""
        return name

    async def execute_cli(self, title: str, args: list[str], timeout: int = 900) -> None:
        if self.action_running:
            self.notify("Une action est déjà en cours.", severity="warning")
            return
        self.action_running = True
        if self.status_widget is not None:
            self.status_widget.update(f"Exécution : ola {' '.join(args)} …")
        try:
            code, output = await asyncio.to_thread(run_cli, args, timeout)
            heading = f"{title}\nCommande : ola {' '.join(args)}\nCode de sortie : {code}\n\n"
            self.push_screen(OutputScreen(title, heading + output))
            if code == 0:
                self.notify("Action terminée.")
            else:
                self.notify(f"La commande a échoué (code {code}).", severity="error")
        finally:
            self.action_running = False
            await self.refresh_snapshot(force=True)

    def action_refresh(self) -> None:
        if not self.refreshing and not self.action_running:
            self.run_worker(self.refresh_snapshot(force=True), group="refresh", exclusive=True)

    def action_use_model(self) -> None:
        model = self._require_model()
        if not model:
            return

        def done(confirmed: bool) -> None:
            if confirmed:
                self.run_worker(
                    self.execute_cli("Utiliser un modèle", ["use", model]),
                    group="actions",
                    exclusive=True,
                )

        self.push_screen(
            ConfirmScreen(
                "Utiliser ce modèle ?",
                f"ola use {model}\n\nLes autres modèles seront déchargés de la RAM, puis ce modèle sera chargé et deviendra le défaut de ola.",
                "Utiliser",
            ),
            done,
        )

    def action_delete_model(self) -> None:
        model = self._require_model()
        if not model:
            return
        is_default = normalize_model(model) == normalize_model(self.snapshot.default_model)
        args = ["delete", model, "--force"] if is_default else ["delete", model]
        consequence = (
            "C'est le modèle par défaut actuel : après suppression, ola choisira un autre modèle restant ou retirera le défaut enregistré."
            if is_default
            else "Le modèle sera déchargé de la RAM si nécessaire, puis supprimé du disque."
        )

        def done(confirmed: bool) -> None:
            if confirmed:
                self.run_worker(
                    self.execute_cli("Supprimer un modèle", args),
                    group="actions",
                    exclusive=True,
                )

        self.push_screen(
            ConfirmScreen(
                "Suppression définitive",
                f"Supprimer définitivement {model} du disque ?\n\n{consequence}\n\nCette action est irréversible sans nouveau téléchargement.",
                "Supprimer",
            ),
            done,
        )

    def action_unload_model(self) -> None:
        model = self._require_model()
        if model:
            self.run_worker(
                self.execute_cli("Libérer la RAM", ["unload", model]),
                group="actions",
                exclusive=True,
            )

    def action_add_model(self) -> None:
        def done(name: str | None) -> None:
            if name:
                self.run_worker(
                    self.execute_cli("Ajouter et utiliser un modèle", ["use", name]),
                    group="actions",
                    exclusive=True,
                )

        self.push_screen(AddModelScreen(), done)

    def action_warm_model(self) -> None:
        model = self._require_model()
        if model:
            self.run_worker(
                self.execute_cli("Préchauffer un modèle", ["fluid", "warm", model]),
                group="actions",
                exclusive=True,
            )

    def action_preset_model(self) -> None:
        model = self._require_model()
        if model:
            self.run_worker(
                self.execute_cli("Preset fluidité", ["fluid", "preset", model], timeout=120),
                group="actions",
                exclusive=True,
            )

    def action_bench_model(self) -> None:
        model = self._require_model()
        if not model:
            return

        def done(confirmed: bool) -> None:
            if confirmed:
                self.run_worker(
                    self.execute_cli("Benchmark classique", ["bench", model], timeout=1200),
                    group="actions",
                    exclusive=True,
                )

        self.push_screen(
            ConfirmScreen(
                "Lancer le benchmark ?",
                f"ola bench {model}\n\nLe test peut prendre du temps et charger/décharger des modèles en RAM. Il ne modifie ni la configuration ni les fichiers des modèles.",
                "Benchmarker",
            ),
            done,
        )

    def action_stream_bench_model(self) -> None:
        model = self._require_model()
        if not model:
            return

        def done(confirmed: bool) -> None:
            if confirmed:
                self.run_worker(
                    self.execute_cli(
                        "Benchmark streaming / fluidité",
                        ["bench", "--stream", model],
                        timeout=1200,
                    ),
                    group="actions",
                    exclusive=True,
                )

        self.push_screen(
            ConfirmScreen(
                "Lancer le benchmark streaming ?",
                f"ola bench --stream {model}\n\nLe test mesure le premier token visible et la régularité du flux. Il peut charger/décharger des modèles en RAM, sans modifier la configuration.",
                "Benchmarker",
            ),
            done,
        )

    def action_speed_status(self) -> None:
        self.run_worker(
            self.execute_cli("Pack Speed", ["speed"], timeout=120),
            group="actions",
            exclusive=True,
        )

    def action_fluid_status(self) -> None:
        self.run_worker(
            self.execute_cli("Fluidité", ["fluid"], timeout=120),
            group="actions",
            exclusive=True,
        )

    def action_logs(self) -> None:
        self.push_screen(LogsScreen())

    def action_cycle_theme(self) -> None:
        available = set(getattr(self, "available_themes", {}) or {})
        candidates = [name for name in THEME_CYCLE if not available or name in available]
        if not candidates:
            self.notify("Aucun thème alternatif disponible.", severity="warning")
            return
        self.theme_index = (self.theme_index + 1) % len(candidates)
        try:
            self.theme = candidates[self.theme_index]
            self.notify(f"Thème : {self.theme}")
        except Exception as exc:
            self.notify(f"Thème indisponible : {exc}", severity="warning")


def main() -> None:
    OlaTui().run()


if __name__ == "__main__":
    main()
OLA_TUI_PY
  chmod 0755 "$tmp" || { rm -f "$tmp"; return 1; }
  mv -f "$tmp" "$target"
}

write_ola_tui_requirements(){
  local target=$1 tmp
  tmp=$(mktemp "${target}.tmp-XXXXXX") || return 1
  cat > "$tmp" <<'EOF'
linkify-it-py==2.2.0
markdown-it-py==4.2.0
mdit-py-plugins==0.6.1
mdurl==0.1.2
platformdirs==4.13.4
Pygments==2.21.0
rich==15.0.0
textual==8.2.8
typing_extensions==4.16.0
EOF
  chmod 0644 "$tmp" || { rm -f "$tmp"; return 1; }
  mv -f "$tmp" "$target"
}

install_ola_tui_files(){
  install -d -m 0755 "$OLA_INSTALL_DIR" || return 1
  write_ola_tui_python_file "$OLA_TUI_FILE" || return 1
  write_ola_tui_requirements "$OLA_TUI_REQUIREMENTS" || return 1
}

tui_textual_version(){
  [[ -x "$OLA_TUI_PYTHON" ]] || return 1
  "$OLA_TUI_PYTHON" -c 'import importlib.metadata; print(importlib.metadata.version("textual"))' 2>/dev/null
}

tui_environment_ready(){
  [[ -f "$OLA_TUI_FILE" && -x "$OLA_TUI_PYTHON" ]] || return 1
  [[ -n "$(tui_textual_version)" ]]
}

show_tui_status(){
  local version=""
  echo "--- Ola TUI (Textual) ---"
  echo "Application : $OLA_TUI_FILE"
  if [[ -f "$OLA_TUI_FILE" ]]; then
    echo "  fichier Python : présent"
  else
    echo "  fichier Python : absent"
  fi
  echo "Environnement : $OLA_TUI_VENV"
  if [[ -x "$OLA_TUI_PYTHON" ]]; then
    echo "  Python isolé : présent ($OLA_TUI_PYTHON)"
  else
    echo "  Python isolé : absent"
  fi
  if version=$(tui_textual_version); then
    echo "  Textual : $version (version épinglée attendue : $OLA_TUI_TEXTUAL_VERSION)"
  else
    echo "  Textual : non importable"
  fi
  if tui_environment_ready; then
    ok "TUI prête. Lancement : ola tui"
    return 0
  fi
  warn "TUI non prête. Le reste de ola fonctionne sans elle. Réparation : sudo ola tui install (ou relancer le setup)."
  return 1
}

install_tui_environment(){
  [[ $EUID -eq 0 ]] || { err "TUI installation requires root."; return 1; }
  info "Installing the optional Textual TUI in an isolated Python environment..."
  install_ola_tui_files || { err "Could not write the TUI files in $OLA_INSTALL_DIR."; return 1; }

  if ! command -v python3 >/dev/null 2>&1; then
    apt_install python3 python3-venv || { err "Could not install Python 3 for the TUI."; return 1; }
  fi
  if ! python3 -c 'import sys; raise SystemExit(0 if sys.version_info >= (3, 9) else 1)' >/dev/null 2>&1; then
    err "Python 3.9 or newer is required for Textual; found: $(python3 --version 2>&1 || echo unknown)"
    return 1
  fi

  # A distribution venv can be left partially created without pip when the
  # python3-venv package is missing. Treat "python exists but pip does not"
  # as a broken environment, install the package, and recreate it cleanly.
  if ! { [[ -x "$OLA_TUI_PYTHON" ]] && "$OLA_TUI_PYTHON" -m pip --version >/dev/null 2>&1; }; then
    if ! python3 -m venv --clear "$OLA_TUI_VENV"; then
      warn "Python venv creation failed; installing python3-venv and retrying..."
      apt_install python3-venv || { err "Could not install python3-venv."; return 1; }
      python3 -m venv --clear "$OLA_TUI_VENV" || { err "Could not create the TUI Python environment: $OLA_TUI_VENV"; return 1; }
    fi
    if ! "$OLA_TUI_PYTHON" -m pip --version >/dev/null 2>&1; then
      if ! "$OLA_TUI_PYTHON" -m ensurepip --upgrade >/dev/null 2>&1; then
        warn "pip is missing from the Python venv; installing python3-venv and recreating it..."
        apt_install python3-venv || { err "Could not install python3-venv."; return 1; }
        python3 -m venv --clear "$OLA_TUI_VENV" || { err "Could not recreate the TUI Python environment: $OLA_TUI_VENV"; return 1; }
      fi
    fi
    "$OLA_TUI_PYTHON" -m pip --version >/dev/null 2>&1 \
      || { err "pip is unavailable in the TUI Python environment."; return 1; }
  fi

  info "Installing pinned Python packages for Textual $OLA_TUI_TEXTUAL_VERSION (network access to PyPI is required)..."
  if ! "$OLA_TUI_PYTHON" -m pip install --disable-pip-version-check --no-input -r "$OLA_TUI_REQUIREMENTS"; then
    err "Could not install the pinned Textual packages from PyPI."
    return 1
  fi
  if ! tui_environment_ready; then
    err "The TUI environment was created but Textual could not be imported."
    return 1
  fi
  ok "TUI installed: Textual $(tui_textual_version). Launch it with: ola tui"
}

repair_tui_environment(){
  require_root
  install_ola_command
  if ! apt_update; then
    warn "apt update failed; trying the TUI installation with the existing package lists."
  fi
  install_tui_environment || die "TUI installation failed. The rest of ola remains available; check the network/PyPI access, then retry: sudo ola tui install"
}

launch_ola_tui(){
  local cli=""
  if [[ ! -t 0 || ! -t 1 ]]; then
    die "ola tui requires an interactive terminal. Use the text commands instead (for example: ola status, ola models, ola fluid)."
  fi
  if ! tui_environment_ready; then
    err "The Textual TUI is not installed or its Python environment is incomplete."
    echo "Repair it with: sudo ola tui install" >&2
    echo "The classic interface remains available with: ola" >&2
    return 1
  fi
  if [[ -x "$OLA_COMMAND" ]]; then
    cli="$OLA_COMMAND"
  else
    cli=$(script_source_path) || die "Could not locate the ola command to give to the TUI."
  fi
  info "Starting the Ola Textual interface. Press q to quit."
  OLA_TUI_CLI="$cli" OLA_TUI_API_URL="http://127.0.0.1:11434" exec "$OLA_TUI_PYTHON" "$OLA_TUI_FILE"
}

case "${1:-}" in
  --help|-h|help)
    usage
    ;;
  status)
    show_status
    ;;
  doctor)
    show_doctor
    ;;
  test)
    run_ola_test
    ;;
  bench)
    if [[ "${2:-}" == "--stream" ]]; then
      run_stream_bench "${3:-}"
    else
      run_bench "${2:-}"
    fi
    ;;
  fluid)
    case "${2:-status}" in
      status)
        show_fluid_status
        ;;
      warm)
        warm_model_command "${3:-}"
        ;;
      preset)
        fluid_preset "${3:-}"
        ;;
      bench)
        run_stream_bench "${3:-}"
        ;;
      keepalive)
        if [[ -z "${3:-}" ]]; then
          err "Usage: ola fluid keepalive <durée|reset> (exemples : 30m, 1h, 2h30m, 3600, -1 ; reset = retour à 5m)"
          exit 1
        fi
        if [[ "$3" == "reset" ]]; then
          keepalive_target="5m"
        elif is_valid_keep_alive "$3"; then
          keepalive_target="$3"
        else
          err "Invalid keep-alive duration: $3 (expected something like 30m, 1h, 2h30m, 3600 seconds, or -1; reset restores 5m)"
          exit 1
        fi
        require_root
        install_ola_command
        require_supervisor_running
        ensure_watchdog
        apply_keep_alive "$keepalive_target"
        ;;
      *)
        err "Usage: ola fluid [status|warm [model]|preset [model]|bench [model]|keepalive <duration|reset>]"
        exit 1
        ;;
    esac
    ;;
  tui)
    case "${2:-launch}" in
      launch)
        launch_ola_tui
        ;;
      install)
        repair_tui_environment
        ;;
      status)
        show_tui_status
        ;;
      *)
        err "Usage: ola tui [install|status] (no argument launches the interface)"
        exit 1
        ;;
    esac
    ;;
  speed)
    case "${2:-status}" in
      status)
        show_speed
        ;;
      apply)
        require_root
        install_ola_command
        require_supervisor_running
        ensure_watchdog
        apply_speed_mode speed
        ;;
      reset|off)
        require_root
        install_ola_command
        require_supervisor_running
        ensure_watchdog
        apply_speed_mode balanced
        ;;
      *)
        err "Usage: ola speed [status|apply|reset]"
        exit 1
        ;;
    esac
    ;;
  use)
    require_root
    if [[ -z "${2:-}" ]]; then
      err "Usage: ola use <model> (example: ola use qwen3:1.7b)"
      exit 1
    fi
    install_ola_command
    require_supervisor_running
    ensure_watchdog
    switch_model "$2"
    ;;
  models)
    if [[ -t 0 && -t 1 ]]; then
      model_manager
    else
      show_installed_models
    fi
    ;;
  ps)
    show_loaded_models
    ;;
  delete|rm)
    require_root
    if [[ -z "${2:-}" ]]; then
      err "Usage: ola delete <model> [--force] (example: ola delete qwen3:1.7b)"
      exit 1
    fi
    delete_force=0
    if [[ "${3:-}" == "--force" ]]; then
      delete_force=1
    elif [[ -n "${3:-}" ]]; then
      err "Unknown delete option: $3 (only --force is supported)"
      exit 1
    fi
    install_ola_command
    require_supervisor_running
    ensure_watchdog
    delete_model_command "$2" "$delete_force"
    ;;
  unload)
    require_root
    install_ola_command
    require_supervisor_running
    ensure_watchdog
    unload_models_command "${2:-}"
    ;;
  watchdog)
    show_watchdog
    ;;
  watchdog-daemon)
    require_root
    run_watchdog_daemon
    ;;
  recover)
    require_root
    install_ola_command
    require_supervisor_running
    ensure_watchdog
    recover_services
    ;;
  logs)
    show_logs
    ;;
  setup)
    require_root
    check_system
    setup_all
    ;;
  start|restart)
    require_root
    install_ola_command
    require_supervisor_running
    ensure_watchdog
    restart_services
    ;;
  stop)
    require_root
    install_ola_command
    require_supervisor_running
    stop_tunnel
    ;;
  "")
    echo "===================================="
    echo " Ollama + Cloudflare Tunnel Manager"
    echo "===================================="
    echo "1) Full setup (Ollama + model + tunnel)"
    echo "2) Status"
    echo "3) Doctor (full diagnostic)"
    echo "4) Test API + model"
    echo "5) Show logs"
    echo "6) Start/restart Ollama and tunnel"
    echo "7) Recover stopped/unhealthy services"
    echo "8) Use another model (unload current from RAM first)"
    echo "9) Unload loaded model(s) from RAM"
    echo "10) Delete a model from disk"
    echo "11) Watchdog status"
    echo "12) Benchmark vitesse (ola bench)"
    echo "13) Vitesse / Pack Speed (état)"
    echo "14) Fluidité (état, ola fluid)"
    echo "15) Stop tunnel"
    echo "16) Exit"
    if ! choice=$(prompt_value "Choice [16]: " "16"); then
      warn "No input received; exiting."
      exit 0
    fi
    case "$choice" in
      1) require_root; check_system; setup_all ;;
      2) show_status ;;
      3) show_doctor ;;
      4) run_ola_test ;;
      5) show_logs ;;
      6) require_root; install_ola_command; require_supervisor_running; ensure_watchdog; restart_services ;;
      7) require_root; install_ola_command; require_supervisor_running; ensure_watchdog; recover_services ;;
      8)
        require_root
        install_ola_command
        require_supervisor_running
        ensure_watchdog
        if ! model_choice=$(prompt_value "Model to use (example qwen3:1.7b): " ""); then
          die "No model received; cancelling model switch."
        fi
        switch_model "$model_choice"
        ;;
      9)
        require_root
        install_ola_command
        require_supervisor_running
        ensure_watchdog
        if ! model_choice=$(prompt_value "Model to unload (blank = all loaded): " ""); then
          die "No input received; cancelling unload."
        fi
        unload_models_command "$model_choice"
        ;;
      10)
        require_root
        install_ola_command
        require_supervisor_running
        ensure_watchdog
        show_installed_models || true
        if ! model_choice=$(prompt_value "Model to permanently delete from disk: " ""); then
          die "No model received; cancelling deletion."
        fi
        delete_force=0
        current_default=$(saved_model_name)
        if [[ "$(normalize_model_name "$current_default")" == "$(normalize_model_name "$model_choice")" ]]; then
          delete_force=1
        fi
        delete_model_command "$model_choice" "$delete_force"
        ;;
      11) show_watchdog ;;
      12) run_bench "" ;;
      13) show_speed ;;
      14) show_fluid_status ;;
      15) require_root; install_ola_command; require_supervisor_running; stop_tunnel ;;
      16) exit 0 ;;
      *) die "Invalid choice." ;;
    esac
    ;;
  *)
    err "Unknown argument: $1 (use --help)."
    usage >&2
    exit 1
    ;;
esac
